// Bubbles, as rules the overlay follows (REQ-LABELS-002, REQ-SIGNALS-005, DECISION-024). Pure, so
// it is tested in Node.
//
// A worker carries a bubble at its desk, as the prototype does: over its screen while it types, and
// over its head while it cheers. A walking worker carries none. A worker reading at the glass office,
// whose story awaits review, calls, and so does a worker asking at the copier for a session waiting
// on a permission prompt. A figure that calls for the human carries a ringed bubble over its head,
// in every view: the team lead's on the phone holds no words, and a calling worker's holds its
// story's ID and title wherever a worker's does, or none for a teal robot with no story. Workers' bubbles
// are in a zoomed office and each office of the split; the overview carries only the calls' rings,
// with no words. Bubbles are kept apart so that none covers another: from the left, a bubble that
// would overlap one already placed is lifted above it.
import { bubbleWords } from '../vocabulary.js'
import { COPIER, GLASS, SPOTS, placed } from './layout.js'

/** How far a bubble's foot sits above a screen's top, and above a robot's head, in plate pixels. */
export const OVER_SCREEN = 5
export const OVER_HEAD = 10
/** The least gap between two bubbles, and between a bubble and the page's edge, in CSS pixels. */
export const GAP = 4
export const EDGE = 2

/**
 * Where a worker's bubble points, in plate pixels: the middle of its foot. Over its screen while it
 * types, over its head while it cheers, and none while it walks.
 * @param {Record<string, import('./layout.js').SpriteEntry>} sprites  The sprite table.
 * @param {{ mode: 'in' | 'seated' | 'cheer' | 'out' | 'go' | 'review' | 'ask', seat: import('./layout.js').Seat }} robot
 * @param {{ name: string, at: { x: number, y: number }, anchor: 'body' | 'foot' }} pose  What it
 *   shows and where.
 * @param {{ x: number, y: number, w: number }} screen  Its desk's screen.
 * @returns {{ x: number, y: number } | null}
 */
export function bubbleAt(sprites, robot, pose, screen) {
  if (robot.mode === 'seated') return { x: screen.x + screen.w / 2, y: screen.y - OVER_SCREEN }
  if (robot.mode !== 'cheer') return null
  const p = placed(sprites, robot.seat, pose.name, pose.at, pose.anchor)
  return { x: pose.at.x, y: p.head - OVER_HEAD }
}

/**
 * Where the team lead's bubble points while it is on the phone, in plate pixels: over its head,
 * where it stands at rest, so the bubble holds still while it rocks.
 * @param {Record<string, import('./layout.js').SpriteEntry>} sprites  The sprite table.
 * @param {{ x: number, y: number }} [at]  Where it stands at rest: its spot by the glass office, or
 *   its place in the lounge while the crew is gathered there (client/office/retro.js).
 * @returns {{ x: number, y: number }}
 */
export function leadBubbleAt(sprites, at = SPOTS.lead) {
  const p = placed(sprites, 'lead', 'lead-talk', at, 'body')
  return { x: at.x, y: p.head - OVER_HEAD }
}

/**
 * Where a worker's bubble points while it reads at the glass office, a call, in plate pixels: over
 * its head, where it stands there at rest, so the bubble holds still while it reads.
 * @param {Record<string, import('./layout.js').SpriteEntry>} sprites  The sprite table.
 * @param {import('./layout.js').Seat} seat  Its robot.
 * @param {number} place  Its place at the glass office, from the left.
 * @returns {{ x: number, y: number }}
 */
export function readerBubbleAt(sprites, seat, place) {
  const at = GLASS[place]
  const p = placed(sprites, seat, `${seat}-read`, at, 'body')
  return { x: at.x, y: p.head - OVER_HEAD }
}

/**
 * Where a worker's bubble points while it asks at the copier, a call, in plate pixels: over its
 * head, where it stands there at rest, so the bubble holds still while it asks.
 * @param {Record<string, import('./layout.js').SpriteEntry>} sprites  The sprite table.
 * @param {import('./layout.js').Seat} seat  Its robot.
 * @param {number} place  Its place at the copier, from the left.
 * @returns {{ x: number, y: number }}
 */
export function askerBubbleAt(sprites, seat, place) {
  const at = COPIER[place]
  const p = placed(sprites, seat, `${seat}-read`, at, 'body')
  return { x: at.x, y: p.head - OVER_HEAD }
}

/**
 * A bubble's point, from the stage: its office, whose it is, a worker by its story or the team lead
 * by null, whether it calls for the human, and where its foot points, in CSS pixels. A worker asking
 * at the copier is also told by the session it asks for, so a teal robot with no story is told from
 * the lead and from another.
 * @typedef {{ office: string, story: string | null, call: boolean, x: number, y: number, prompt?: string }} Point
 */

/**
 * The bubbles a view carries, each with its words and whether it is ringed as a call: in a zoomed
 * office, and in each office of the split, a worker's bubble holds its story's ID and title; the
 * team lead's holds no words. In the overview only calls carry a bubble, and none holds words. A
 * figure whose office isn't in view, or no longer in the state, carries none.
 * @param {Point[]} points  Where each bubble points, from the stage.
 * @param {{ id: string, phases: import('../../shared/state.js').Phase[] }[]} projects  The latest state's.
 * @param {string[] | null} inView  The offices in view, or null for the overview.
 * @returns {{ key: string, text: string, call: boolean, x: number, y: number }[]}
 */
export function speech(points, projects, inView) {
  const phases = new Map(projects.map((p) => [p.id, p.phases]))
  return points.flatMap((p) => {
    const of = phases.get(p.office)
    if (of === undefined) return []
    if (inView === null ? !p.call : !inView.includes(p.office)) return []
    const text = inView === null || p.story === null ? '' : bubbleWords(of, p.story)
    return [{ key: p.prompt === undefined ? `${p.office} ${p.story ?? 'lead'}` : `${p.office} prompt ${p.prompt}`, text, call: p.call, x: p.x, y: p.y }]
  })
}

/**
 * A bubble to place: where its foot points, in CSS pixels, and its size.
 * @typedef {{ key: string, x: number, y: number, width: number, height: number }} Wanted
 */

/**
 * A placed bubble: the middle of its foot, in CSS pixels, and whether it was lifted off its point.
 * @typedef {{ key: string, x: number, y: number, lifted: boolean }} Spread
 */

/**
 * Places bubbles so that none covers another: from the left, each is kept within the page's width,
 * and lifted above any bubble already placed that it would overlap, and kept below the page's top.
 * @param {Wanted[]} wanted
 * @param {number} pageWidth  In CSS pixels.
 * @returns {Spread[]}  In the order placed, from the left.
 */
export function spread(wanted, pageWidth) {
  /** @type {{ l: number, r: number, t: number, b: number }[]} */
  const boxes = []
  /** @type {Spread[]} */
  const out = []
  for (const it of [...wanted].sort((a, b) => a.x - b.x || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0))) {
    const w = it.width
    const h = it.height
    const x = Math.max(w / 2 + EDGE, Math.min(pageWidth - w / 2 - EDGE, it.x))
    let bottom = it.y
    let lifted = false
    // Each lift clears one bubble, so there are never more lifts than bubbles placed.
    for (let guard = 0; guard <= boxes.length; guard++) {
      const hit = boxes.find((p) => x - w / 2 < p.r + GAP && x + w / 2 > p.l - GAP && bottom - h < p.b + GAP && bottom > p.t - GAP)
      if (hit === undefined) break
      bottom = hit.t - GAP - 2
      lifted = true
    }
    if (bottom - h < EDGE) bottom = h + EDGE
    boxes.push({ l: x - w / 2, r: x + w / 2, t: bottom - h, b: bottom })
    out.push({ key: it.key, x, y: bottom, lifted })
  }
  return out
}
