// The page's views and their hashes (spec/architecture.md, "Views"): the overview at `#/`, one
// office zoomed in at `#/office/<id>` (REQ-DOCKS-004), and two side by side at `#/split/<id>,<id>`
// (REQ-DOCKS-005). A kept `#/dock/<id>` opens the same view as `#/office/<id>`, so an address kept
// from before still works. Pure, so it is tested in Node.

/**
 * @typedef {{ kind: 'overview' } | { kind: 'office', id: string } | { kind: 'split', ids: [string, string] }} View
 */

/** @type {View} */
export const OVERVIEW = Object.freeze({ kind: 'overview' })

/**
 * The view a hash names. A hash that names none is the overview.
 * @param {string} hash  location.hash, with or without its '#'.
 * @returns {View}
 */
export function parse(hash) {
  const path = hash.replace(/^#/, '')
  const one = /^\/(?:dock|office)\/([^/,]+)$/.exec(path)
  if (one !== null) {
    const id = decode(one[1])
    return id === null ? OVERVIEW : { kind: 'office', id }
  }
  const split = /^\/split\/([^/,]+),([^/,]+)$/.exec(path)
  if (split !== null) {
    const a = decode(split[1])
    const b = decode(split[2])
    if (a === null || b === null) return OVERVIEW
    // The same office twice is that office, zoomed in.
    return a === b ? { kind: 'office', id: a } : { kind: 'split', ids: [a, b] }
  }
  return OVERVIEW
}

/**
 * The hash of a view.
 * @param {View} view
 * @returns {string}
 */
export function format(view) {
  if (view.kind === 'office') return `#/office/${encodeURIComponent(view.id)}`
  if (view.kind === 'split') return `#/split/${view.ids.map(encodeURIComponent).join(',')}`
  return '#/'
}

/**
 * The offices a view shows, or null for the overview, which shows every office.
 * @param {View} view
 * @returns {string[] | null}
 */
export function shown(view) {
  if (view.kind === 'office') return [view.id]
  if (view.kind === 'split') return [...view.ids]
  return null
}

/**
 * The view that remains once the offices not present have left: a split loses the office that left and
 * zooms in on the other, and a zoomed view whose office left returns to the overview.
 * @param {View} view
 * @param {Set<string>} present  The ids of the offices there are now.
 * @returns {View}
 */
export function settle(view, present) {
  const ids = shown(view)
  if (ids === null) return view
  const left = ids.filter((id) => present.has(id))
  if (left.length === ids.length) return view
  return left.length === 1 ? { kind: 'office', id: left[0] } : OVERVIEW
}

/**
 * What a click on an office does. A click zooms in on it. A Shift-click picks it for the split, the
 * second pick opens the split, and Shift-clicking the picked office again lets it go.
 * @param {{ view: View, picked: string | null }} now
 * @param {string} id  The office clicked.
 * @param {boolean} shift  Whether Shift was held.
 * @returns {{ view: View, picked: string | null }}
 */
export function choose({ view, picked }, id, shift) {
  if (!shift) return { view: { kind: 'office', id }, picked: null }
  if (picked === null) return { view, picked: id }
  if (picked === id) return { view, picked: null }
  return { view: { kind: 'split', ids: [picked, id] }, picked: null }
}

/**
 * Whether two views are the same.
 * @param {View} a
 * @param {View} b
 */
export function same(a, b) {
  return format(a) === format(b)
}

/**
 * @param {string} part
 * @returns {string | null}
 */
function decode(part) {
  try {
    const id = decodeURIComponent(part)
    return id === '' ? null : id
  } catch {
    return null
  }
}
