// The DOM layer over the canvas (DECISION-008): a button named for each project, placed over its
// office in a navigation named Offices, in name order so the keyboard follows the grid
// (REQ-LABELS-001), the one plain line the overview shows when no project is active (REQ-DOCKS-006),
// and the icon button named Overview that a zoomed or split view returns by (REQ-DOCKS-004,
// REQ-DOCKS-005). Each office button's accessible description gives each of its phases' landed
// count and each story at work (REQ-SHIPS-002), from a hidden element it names with
// aria-describedby. Hovering the whiteboard, a sticky note or a figure shows its label by the
// pointer, in an element with role="tooltip" (REQ-LABELS-002). A visually hidden role="status"
// region says in plain words what waits, a line a project (REQ-SIGNALS-005, spec/architecture.md,
// "The overlay"). When the office can't draw, it shows the same state as a list: a region for each
// office in view, with its phases, its stories and what waits, in the labels' words (REQ-DOCKS-007).
// Each worker's bubble is an element over the canvas, its words set as text and never as markup,
// kept apart so none covers another, and hidden from assistive technology, since each office's
// description already names each story at work (REQ-LABELS-002, DECISION-024). A call's bubble is
// ringed, and the status region already says what waits (REQ-SIGNALS-005).
import { spread } from './office/bubbles.js'
import { EMPTY_LINE, NOTHING_WAITS, NO_PHASES } from './vocabulary.js'

/**
 * @typedef {object} Overlay
 * @property {(projects: { id: string, name: string, description: string }[]) => void} update  The
 *   offices, in name order, each with its description.
 * @property {(ids: string[] | null, picked: string | null) => void} show  The offices in view, or
 *   null for every office, and the office picked for a split, if one is.
 * @property {(anchor: ((id: string) => { x: number, y: number } | null) | null) => void} place
 *   Moves each button to its office. Without an anchor, as when the office can't draw, the buttons
 *   stay in the page's flow.
 * @property {(label: string | null, x?: number, y?: number) => void} tip  Shows a label by the
 *   pointer, at a point in CSS pixels from the overlay's top left, or hides it when label is null.
 * @property {(bubbles: { key: string, text: string, call?: boolean, x: number, y: number }[]) => void} bubbles
 *   The bubbles, each by where its foot points, in CSS pixels from the overlay's top left, ringed
 *   when it is a call's; an empty list takes every bubble away.
 * @property {(lines: string[]) => void} status  What waits, a line a project; none when nothing does.
 * @property {(offices: import('./vocabulary.js').ListedOffice[] | null) => void} list  The list
 *   view's offices, in name order, shown when the office can't draw; null keeps the list away.
 */

const SVG = 'http://www.w3.org/2000/svg'

/**
 * Starts the overlay in a container that covers the canvas.
 * @param {HTMLElement} root
 * @param {{ open: (id: string, shift: boolean) => void, overview: () => void }} actions  open: an
 *   office's button was clicked, with or without Shift; overview: the Overview button was clicked.
 * @param {{ places?: string }} [options]  places: the name of the navigation that holds the buttons.
 * @returns {Overlay}
 */
export function overlay(root, actions, { places = 'Offices' } = {}) {
  const back = document.createElement('button')
  back.type = 'button'
  back.className = 'overview'
  back.setAttribute('aria-label', 'Overview')
  back.title = 'Overview (Esc)'
  back.append(icon())
  back.hidden = true
  back.addEventListener('click', () => actions.overview())

  const divider = document.createElement('div')
  divider.className = 'divider'
  divider.hidden = true

  const offices = document.createElement('nav')
  offices.className = 'offices'
  offices.setAttribute('aria-label', places)
  offices.addEventListener('click', (event) => {
    const target = event.target instanceof Element ? event.target.closest('button.office') : null
    if (!(target instanceof HTMLButtonElement) || target.dataset.id === undefined) return
    actions.open(target.dataset.id, event.shiftKey)
  })
  const empty = document.createElement('p')
  empty.className = 'empty'
  empty.textContent = EMPTY_LINE
  empty.hidden = true
  // The descriptions the buttons point at: hidden, so only the buttons' descriptions say them.
  const notes = document.createElement('div')
  notes.hidden = true
  // The label of what is under the pointer (REQ-LABELS-002).
  const label = document.createElement('div')
  label.className = 'tip'
  label.setAttribute('role', 'tooltip')
  label.hidden = true
  // What waits on the human, in plain words, for a screen reader to say as it changes.
  const waits = document.createElement('div')
  waits.className = 'status'
  waits.setAttribute('role', 'status')
  // The list view, for when the office can't draw (REQ-DOCKS-007).
  const sheet = document.createElement('div')
  sheet.className = 'list'
  sheet.hidden = true
  // The workers' bubbles, hidden from assistive technology.
  const speech = document.createElement('div')
  speech.className = 'bubbles'
  speech.setAttribute('aria-hidden', 'true')
  root.append(divider, speech, offices, empty, back, sheet, notes, label, waits)

  /** @type {Map<string, HTMLButtonElement>} */
  const buttons = new Map()
  /** @type {Map<string, HTMLElement>} */
  const descriptions = new Map()
  /** @type {Set<string> | null} */
  let inView = null
  /** @type {((id: string) => { x: number, y: number } | null) | null} */
  let lastAnchor = null
  /** Each office's region in the list view. @type {Map<string, HTMLElement>} */
  const regions = new Map()

  /** @type {Overlay['update']} */
  const update = (projects) => {
    const wanted = new Set(projects.map((p) => p.id))
    for (const [id, button] of buttons) {
      if (!wanted.has(id)) {
        button.remove()
        buttons.delete(id)
        descriptions.get(id)?.remove()
        descriptions.delete(id)
      }
    }
    for (const { id, name, description } of projects) {
      let button = buttons.get(id)
      if (button === undefined) {
        button = document.createElement('button')
        button.type = 'button'
        button.className = 'office'
        button.dataset.id = id
        button.setAttribute('aria-pressed', 'false')
        buttons.set(id, button)
        const note = document.createElement('span')
        note.id = `office-description-${id}`
        notes.append(note)
        descriptions.set(id, note)
        button.setAttribute('aria-describedby', note.id)
      }
      if (button.textContent !== name) button.textContent = name
      const note = descriptions.get(id)
      if (note !== undefined && note.textContent !== description) note.textContent = description
      // Appending in name order keeps the tab order the grid's.
      offices.append(button)
    }
    empty.hidden = projects.length > 0
    place(lastAnchor)
  }

  /** @type {Overlay['show']} */
  const show = (ids, picked) => {
    inView = ids === null ? null : new Set(ids)
    back.hidden = ids === null
    divider.hidden = ids === null || ids.length < 2
    for (const [id, button] of buttons) button.setAttribute('aria-pressed', String(id === picked))
    place(lastAnchor)
    for (const [id, region] of regions) region.hidden = inView !== null && !inView.has(id)
  }

  /** @type {Overlay['place']} */
  const place = (anchor) => {
    lastAnchor = anchor
    offices.classList.toggle('placed', anchor !== null)
    for (const [id, button] of buttons) {
      const at = anchor === null ? null : anchor(id)
      const out = inView !== null && !inView.has(id)
      button.hidden = out || (anchor !== null && at === null)
      if (at === null) {
        button.style.transform = ''
        continue
      }
      button.style.transform = `translate(${Math.round(at.x)}px, ${Math.round(at.y)}px) translate(-50%, 0)`
    }
  }

  /** How far the label sits from the pointer, below and to the right, in CSS pixels. */
  const OFFSET = 14

  /** @type {Overlay['tip']} */
  const tip = (text, x = 0, y = 0) => {
    if (text === null) {
      label.hidden = true
      return
    }
    if (label.textContent !== text) label.textContent = text
    label.hidden = false
    // Below and to the right of the pointer, or above and to the left where that would leave the page.
    const width = label.offsetWidth
    const height = label.offsetHeight
    const left = x + OFFSET + width > root.clientWidth ? x - OFFSET - width : x + OFFSET
    const top = y + OFFSET + height > root.clientHeight ? y - OFFSET - height : y + OFFSET
    label.style.transform = `translate(${Math.round(Math.max(0, left))}px, ${Math.round(Math.max(0, top))}px)`
  }

  /** Each bubble's element, by key. @type {Map<string, HTMLElement>} */
  const said = new Map()
  /** Each bubble's size, by its words and the page's width, which its font follows. @type {Map<string, { width: number, height: number }>} */
  const sizes = new Map()

  /** @type {Overlay['bubbles']} */
  const bubbles = (list) => {
    const wanted = new Set(list.map((b) => b.key))
    for (const [key, element] of said) {
      if (wanted.has(key)) continue
      element.remove()
      said.delete(key)
    }
    if (list.length === 0) return
    const pageWidth = root.clientWidth
    const measured = list.map((b) => {
      let element = said.get(b.key)
      if (element === undefined) {
        element = document.createElement('div')
        element.className = 'bubble'
        speech.append(element)
        said.set(b.key, element)
      }
      // Text, never markup: a title is a project's own words.
      if (element.textContent !== b.text) element.textContent = b.text
      // A call's bubble is ringed; one without words keeps a small size of its own.
      const call = b.call === true
      element.classList.toggle('call', call)
      const sized = `${call ? 'call' : ''}|${b.text}|${pageWidth}`
      let size = sizes.get(sized)
      if (size === undefined) {
        size = { width: element.offsetWidth, height: element.offsetHeight }
        if (sizes.size > 200) sizes.clear()
        sizes.set(sized, size)
      }
      return { key: b.key, x: b.x, y: b.y, width: size.width, height: size.height }
    })
    for (const placedBubble of spread(measured, pageWidth)) {
      const element = said.get(placedBubble.key)
      if (element === undefined) continue
      element.classList.toggle('lifted', placedBubble.lifted)
      const transform = `translate(${Math.round(placedBubble.x)}px, ${Math.round(placedBubble.y)}px) translate(-50%, -100%)`
      if (element.style.transform !== transform) element.style.transform = transform
    }
  }

  /** @type {Overlay['status']} */
  const status = (lines) => {
    const now = [...waits.children].map((line) => line.textContent)
    // Nothing is written while the lines stay the same, so a screen reader isn't told them again.
    if (now.length === lines.length && now.every((text, i) => text === lines[i])) return
    waits.replaceChildren(
      ...lines.map((text) => {
        const line = document.createElement('p')
        line.textContent = text
        return line
      }),
    )
  }

  /** @type {Overlay['list']} */
  const list = (listed) => {
    root.classList.toggle('listed', listed !== null)
    sheet.hidden = listed === null
    regions.clear()
    if (listed === null) {
      sheet.replaceChildren()
      return
    }
    sheet.replaceChildren(
      ...listed.map((office) => {
        const region = section(office)
        region.hidden = inView !== null && !inView.has(office.id)
        regions.set(office.id, region)
        return region
      }),
    )
  }

  return { update, show, place, tip, bubbles, status, list }
}

/**
 * An office's region in the list view: its name as a heading, then its phases with their stories,
 * what waits, and the gate runs under way.
 * @param {import('./vocabulary.js').ListedOffice} office
 */
function section(office) {
  const region = document.createElement('section')
  region.className = 'listed-office'
  const heading = document.createElement('h2')
  heading.id = `list-${office.id}`
  heading.textContent = office.name
  region.setAttribute('aria-labelledby', heading.id)
  region.append(heading)

  if (office.phases.length === 0) {
    const none = document.createElement('p')
    none.textContent = NO_PHASES
    region.append(none)
  } else {
    const phases = office.phases.map((phase) => {
      const item = document.createElement('li')
      item.append(phase.label)
      if (phase.stories.length > 0) item.append(items(phase.stories, `Stories of ${phase.label.split(' · ')[0]}`))
      return item
    })
    region.append(items(phases, 'Phases'))
  }

  if (office.waits.length === 0) {
    const none = document.createElement('p')
    none.textContent = NOTHING_WAITS
    region.append(none)
  } else {
    region.append(...titled(items(office.waits, 'What waits'), `list-${office.id}-waits`))
  }
  if (office.running.length > 0) region.append(...titled(items(office.running, 'Under way'), `list-${office.id}-running`))
  return region
}

/**
 * A list under a heading that says its name, which names it in turn.
 * @param {HTMLUListElement} ul
 * @param {string} id  The heading's id.
 * @returns {[HTMLHeadingElement, HTMLUListElement]}
 */
function titled(ul, id) {
  const heading = document.createElement('h3')
  heading.id = id
  heading.textContent = ul.getAttribute('aria-label')
  ul.removeAttribute('aria-label')
  ul.setAttribute('aria-labelledby', id)
  return [heading, ul]
}

/**
 * A list, named for what it holds.
 * @param {(string | HTMLLIElement)[]} entries  Each a line, or an item already made.
 * @param {string} name
 */
function items(entries, name) {
  const ul = document.createElement('ul')
  ul.setAttribute('aria-label', name)
  for (const entry of entries) {
    if (typeof entry === 'string') {
      const item = document.createElement('li')
      item.textContent = entry
      ul.append(item)
    } else ul.append(entry)
  }
  return ul
}

/** The Overview button's icon: four small squares, the offices on their grid. */
function icon() {
  const svg = document.createElementNS(SVG, 'svg')
  svg.setAttribute('viewBox', '0 0 16 16')
  svg.setAttribute('width', '16')
  svg.setAttribute('height', '16')
  svg.setAttribute('aria-hidden', 'true')
  svg.setAttribute('focusable', 'false')
  for (const [x, y] of [[2, 2], [9, 2], [2, 9], [9, 9]]) {
    const rect = document.createElementNS(SVG, 'rect')
    rect.setAttribute('x', String(x))
    rect.setAttribute('y', String(y))
    rect.setAttribute('width', '5')
    rect.setAttribute('height', '5')
    rect.setAttribute('rx', '1')
    rect.setAttribute('fill', 'currentColor')
    svg.append(rect)
  }
  return svg
}
