// Frames on demand: a frame is drawn only while something moves or the state changes, or an image
// has loaded (spec/architecture.md, "The office"). Pure apart from the scheduler it is given, so it
// is tested in Node.

/**
 * A loop that draws when woken, and keeps drawing only while the drawing says something still
 * moves.
 * @param {(now: number) => boolean} draw  Draws one frame; returns whether anything still moves.
 * @param {(callback: (now: number) => void) => unknown} request  requestAnimationFrame, or a stand-in.
 * @returns {{ wake: () => void, readonly pending: boolean }}
 */
export function frames(draw, request) {
  let pending = false
  const tick = (/** @type {number} */ now) => {
    pending = false
    if (draw(now)) wake()
  }
  const wake = () => {
    if (pending) return
    pending = true
    request(tick)
  }
  return {
    wake,
    get pending() {
      return pending
    },
  }
}
