// Launch day in the office, as rules the stage follows (REQ-SHIPS-005). Pure, so it is tested in Node.
//
// When a project is tagged `mvp`, its office holds launch day: bunting goes up on the back wall, the
// balloons and the cake come out, confetti falls once, and every robot in the room cheers once. That
// is an event, played once at loudness 3, below anything that calls for the human: a robot at a call
// keeps calling, and a robot on its way keeps walking. The props then stay, at rest. A page loaded
// later, or an office out of view, draws them at rest, with no confetti. Under reduced motion the
// props are up at once, no confetti falls, and the robots hold their cheer without the hop.
import { motion, once } from '../vocabulary.js'
import { PLATE } from './layout.js'

/**
 * A prop placed on the plate: its sprite, where the middle of its foot stands, and its height from
 * its first to its last opaque row, in plate pixels. The bunting hangs on the back wall, across the
 * top of the window, three garlands side by side; the balloons stand right of the sofa, by the
 * plant, and the cake on the coffee table in the lounge.
 * @typedef {Readonly<{ sprite: 'props-bunting' | 'props-balloons' | 'props-cake', at: Readonly<{ x: number, y: number }>, height: number }>} Prop
 */

/** @type {readonly Prop[]} */
export const PROPS = Object.freeze([
  Object.freeze({ sprite: /** @type {const} */ ('props-bunting'), at: Object.freeze({ x: 400, y: 90 }), height: 58 }),
  Object.freeze({ sprite: /** @type {const} */ ('props-bunting'), at: Object.freeze({ x: 557, y: 90 }), height: 58 }),
  Object.freeze({ sprite: /** @type {const} */ ('props-bunting'), at: Object.freeze({ x: 714, y: 90 }), height: 58 }),
  Object.freeze({ sprite: /** @type {const} */ ('props-balloons'), at: Object.freeze({ x: 1040, y: 545 }), height: 130 }),
  Object.freeze({ sprite: /** @type {const} */ ('props-cake'), at: Object.freeze({ x: 905, y: 552 }), height: 46 }),
])

/** Of launch day, the share at its start spent bringing the props out, and standing up before the arms go up. */
export const OUT = 0.3
export const RISE = 0.2
/** How far the bunting drops and the balloons rise as they come out, at amplitude 1, in plate pixels. */
export const DROP = 60
/** How many pieces of confetti fall, and their colours: teal, amber and coral, as the props are. */
export const PIECES = 72
export const CONFETTI = Object.freeze(['#2bb3a0', '#f0a83a', '#e0705a'])

/**
 * Whether a project's office holds launch day, or keeps its props up: once it is tagged `mvp`.
 * @param {{ mvp?: boolean }} project
 */
export function launched(project) {
  return project.mvp === true
}

/**
 * How long launch day plays, in milliseconds: one cycle of an event, held as long under reduced
 * motion, so the robots' cheer lasts the same.
 */
export function partyLength() {
  return once(motion('office.launch'))
}

/**
 * How far the props have come out at a share of launch day: from 0, not yet, to 1, out and at rest.
 * Under reduced motion they are out at once.
 * @param {number} t  From 0 to 1.
 * @param {boolean} [reduced]
 */
export function comeOut(t, reduced = false) {
  if (motion('office.launch', { reduced }).amplitude === 0) return 1
  const k = Math.min(1, Math.max(0, t / OUT))
  return 1 - (1 - k) ** 3
}

/**
 * Where a prop is drawn as it comes out, and how opaque: the bunting drops onto the wall from above
 * and the balloons rise from below, by the launch's amplitude, and every prop fades in. At rest, out
 * at 1, it is at its place.
 * @param {Prop} prop
 * @param {number} out  From comeOut.
 * @returns {{ at: { x: number, y: number }, alpha: number }}
 */
export function propAt(prop, out) {
  const shift = (1 - out) * DROP * motion('office.launch').amplitude
  const dy = prop.sprite === 'props-bunting' ? -shift : prop.sprite === 'props-balloons' ? shift : 0
  return { at: { x: prop.at.x, y: prop.at.y + dy }, alpha: out }
}

/**
 * A robot's cheer at a share of launch day: standing for its first part, then cheering with a hop
 * that rises and falls once, by the launch's amplitude, so without one under reduced motion.
 * @param {number} t  From 0 to 1.
 * @param {boolean} [reduced]
 * @returns {{ up: boolean, lift: number }}  up: its arms are up; lift: how high it hops, from 0 to
 *   the launch's amplitude.
 */
export function cheerAt(t, reduced = false) {
  const amplitude = motion('office.launch', { reduced }).amplitude
  if (t < RISE) return { up: false, lift: 0 }
  return { up: true, lift: Math.sin((Math.min(1, (t - RISE) / (1 - RISE))) * Math.PI) * amplitude }
}

/**
 * A number from 0 to 1 that a piece of confetti keeps, the same on every machine.
 * @param {number} i
 * @param {number} salt
 */
function noise(i, salt) {
  const v = Math.sin(i * 12.9898 + salt * 78.233) * 43758.5453
  return v - Math.floor(v)
}

/**
 * The confetti at a share of launch day, in plate pixels: each piece starts above the room at its own
 * moment, falls to below its floor, swaying, and turns as it goes. It falls once: none before the
 * day starts or after it ends, and none under reduced motion.
 * @param {number} t  From 0 to 1.
 * @param {boolean} [reduced]
 * @returns {{ x: number, y: number, angle: number, colour: string, w: number, h: number }[]}
 */
export function confetti(t, reduced = false) {
  const m = motion('office.launch', { reduced })
  if (m.amplitude === 0 || t <= 0 || t >= 1) return []
  /** @type {{ x: number, y: number, angle: number, colour: string, w: number, h: number }[]} */
  const pieces = []
  for (let i = 0; i < PIECES; i++) {
    const start = noise(i, 1) * 0.35
    const fall = 0.55 + noise(i, 2) * 0.1
    const k = (t - start) / fall
    if (k <= 0 || k >= 1) continue
    const sway = Math.sin(k * Math.PI * 3 + noise(i, 3) * Math.PI * 2) * 14 * m.amplitude
    pieces.push({
      x: noise(i, 4) * PLATE.width + sway,
      y: -12 + k * (PLATE.height + 24),
      angle: k * Math.PI * 4 * (noise(i, 5) < 0.5 ? -1 : 1) + noise(i, 6) * Math.PI,
      colour: CONFETTI[i % CONFETTI.length],
      w: 5 + noise(i, 7) * 3,
      h: 3 + noise(i, 8) * 2,
    })
  }
  return pieces
}

/**
 * The box a prop is drawn in, in plate pixels, placed by the middle of its foot at a point, at its
 * height on the plate.
 * @param {Record<string, import('./layout.js').SpriteEntry>} sprites  The sprite table.
 * @param {Prop} prop
 * @param {{ x: number, y: number }} at
 * @returns {{ left: number, top: number, width: number, height: number, head: number }}  head: the
 *   height of its first opaque row on the plate.
 */
export function propBox(sprites, prop, at) {
  const entry = sprites[prop.sprite]
  if (entry === undefined) throw new Error(`sprites.json has no ${prop.sprite}`)
  const [width, height, top, foot, bodyX] = entry
  const scale = prop.height / (foot - top)
  return { left: at.x - bodyX * scale, top: at.y - foot * scale, width: width * scale, height: height * scale, head: at.y - prop.height }
}
