// The office's calls, as rules the stage follows (REQ-SIGNALS-002, REQ-SIGNALS-003, REQ-SIGNALS-004,
// REQ-SIGNALS-005). Pure, so it is tested in Node.
//
// A call is what needs the human, and only a call moves at loudness 4: the team lead on the phone,
// a worker reading at the glass office and a worker asking at the copier. While a question is parked
// in a project's docs/queue.md, its team lead talks on its headset, rocking a little on its wheel,
// and the desk phone in the glass office blinks its light. Once the last question leaves the queue,
// the lead and the light go back to rest. A call keeps moving for as long as it lasts, gently under
// reduced motion, when everything else stands still.
import { motion } from '../vocabulary.js'

/** How high the team lead rocks on its wheel as it talks, at amplitude 1, in its own pixels. */
export const TALK = 6

/** The phone light's glow, as alpha: its middle, and how far it swings either side at amplitude 1. */
export const GLOW = 0.45
export const BLINK = 0.4

/**
 * Whether a project's team lead is on the phone: while any question is parked in its queue. The
 * state's questions leave out review questions, which a worker at the glass office shows instead.
 * @param {import('../../shared/state.js').Question[]} questions
 */
export function onPhone(questions) {
  return questions.length > 0
}

/**
 * A call's swing at a moment, from 0 to 1 and back, once a cycle of its rate; 0 when it stands still.
 * @param {number} ms
 * @param {{ rate: number }} m
 */
function swing(ms, m) {
  if (m.rate === 0) return 0
  return 0.5 - 0.5 * Math.cos((2 * Math.PI * m.rate * ms) / 1000)
}

/**
 * How far the team lead on the phone rises on its wheel at a moment, in its own pixels.
 * @param {number} ms  How long it has talked, in milliseconds.
 * @param {boolean} [reduced]
 */
export function talkBob(ms, reduced = false) {
  const m = motion('lead.phone', { reduced })
  return swing(ms, m) * TALK * m.amplitude
}

/**
 * How bright the desk phone's light is at a moment, as alpha, while the lead is on the phone.
 * @param {number} ms
 * @param {boolean} [reduced]
 */
export function phoneGlow(ms, reduced = false) {
  const m = motion('lead.phone', { reduced })
  return GLOW + BLINK * m.amplitude * (2 * swing(ms, m) - 1)
}

// A T3 story awaiting review is its worker reading at the glass office, a call, until the story is
// reviewed (REQ-SIGNALS-003). Two reviews stand side by side in front of the glass office, in plan
// order; a third waits, undrawn, until a place is free. A worker still at work on the story walks
// there from its desk, which keeps its chair, and its screen dims; any other walks in from the front
// of the room. Once the review is gone, the worker walks back to its desk if it still works, or else
// off the floor.

/** How many reviews stand at the glass office at once. */
export const READERS = 2

/** How high a worker reading at the glass office lifts its sheet, at amplitude 1, in its own pixels. */
export const READ = 4

/**
 * The reviews that stand at the glass office: the first two in plan order, each with its place there,
 * from the left, and its story's tier.
 * @param {import('../../shared/state.js').Review[]} reviews  In plan order, as the state keeps them.
 * @param {(story: string) => 'T1' | 'T2' | 'T3'} tierOf
 * @returns {{ story: string, tier: 'T1' | 'T2' | 'T3', place: number }[]}
 */
export function atGlass(reviews, tierOf) {
  return reviews.slice(0, READERS).map((review, place) => ({ story: review.story, tier: tierOf(review.story), place }))
}

/** @typedef {{ x: number, y: number }} Point */

/**
 * The walk from a point on the floor to a point in front of the glass office, in plate pixels. Left
 * of the lounge, it goes down to the aisle under the desks, along it, and up past the lounge's
 * corner, as the prototype walks it; right of it, along the gap above the lounge. A point in front
 * of the glass office already goes straight across.
 * @param {Point} from
 * @param {Point} to
 * @returns {Point[]}
 */
export function toGlass(from, to) {
  /** @type {Point[]} */
  const route = [from]
  if (from.x < LOUNGE.x) route.push({ x: from.x, y: AISLE }, { x: LOUNGE.x - 30, y: AISLE }, { x: LOUNGE.x + 40, y: ABOVE })
  else if (from.y > ABOVE) route.push({ x: from.x, y: ABOVE })
  route.push(to)
  return route.filter((p, i) => i === 0 || p.x !== route[i - 1].x || p.y !== route[i - 1].y)
}

/** The aisle under the desks, the gap above the lounge, and the lounge's left corner, in plate pixels. */
export const AISLE = 458
export const ABOVE = 418
export const LOUNGE = Object.freeze({ x: 650 })

/**
 * How long a walk is, in plate pixels.
 * @param {Point[]} route
 */
export function routeLength(route) {
  let length = 0
  for (let i = 1; i < route.length; i++) length += Math.hypot(route[i].x - route[i - 1].x, route[i].y - route[i - 1].y)
  return length
}

/**
 * Where a walk has got to once it has gone a distance, and which way it heads there: up the room,
 * down it, or across, facing right (1) or left (-1). Past its end, it is at its end.
 * @param {Point[]} route
 * @param {number} walked  In plate pixels.
 * @returns {{ x: number, y: number, heading: 'up' | 'down' | 'across', face: number, done: boolean }}
 */
export function along(route, walked) {
  let left = Math.max(0, walked)
  for (let i = 1; i < route.length; i++) {
    const a = route[i - 1]
    const b = route[i]
    const d = Math.hypot(b.x - a.x, b.y - a.y)
    if (d === 0) continue
    const heading = Math.abs(b.y - a.y) > Math.abs(b.x - a.x) ? (b.y < a.y ? 'up' : 'down') : 'across'
    const face = Math.sign(b.x - a.x) || 1
    if (left < d || i === route.length - 1) {
      const k = Math.min(1, left / d)
      return { x: a.x + (b.x - a.x) * k, y: a.y + (b.y - a.y) * k, heading, face, done: left >= d }
    }
    left -= d
  }
  const end = route[route.length - 1]
  return { x: end.x, y: end.y, heading: 'up', face: 1, done: true }
}

/**
 * How far a worker reading at the glass office lifts its sheet at a moment, in its own pixels: a
 * call, so it keeps moving, gently under reduced motion.
 * @param {number} ms  How long it has read, in milliseconds.
 * @param {boolean} [reduced]
 */
export function readBob(ms, reduced = false) {
  const m = motion('worker.read', { reduced })
  return swing(ms, m) * READ * m.amplitude
}

// A session waiting on a permission prompt sends a worker to the copier to ask, a call, and the
// copier's red light blinks while any prompt waits (REQ-SIGNALS-004). The worker is the prompt's
// story's worker, or else the worker at work in the prompt's session, or else a teal robot with no
// story. Two stand side by side at the copier, in the order the prompts came; a third waits,
// undrawn, until a place is free. Once the prompt clears, the worker walks back to its desk if it
// still works, or else off the floor.

/** How many prompts stand at the copier at once. */
export const ASKERS = 2

/** How high a worker asking at the copier lifts its sheet, at amplitude 1, in its own pixels. */
export const ASK = 4

/** The lane below the desks a worker walks along to and from the copier, in plate pixels, as the prototype walks it. */
export const LANE = 472

/** How far right of its place at the copier a worker leaves the lane, in plate pixels. */
export const LANE_OFF = 55

/**
 * A prompt at the copier: the waiting session, the worker that asks for it by its story, or null
 * for a teal robot with no story, that worker's tier, and its place at the copier, from the left.
 * @typedef {{ session: string, story: string | null, tier: 'T1' | 'T2' | 'T3', place: number }} Asker
 */

/**
 * The prompts that stand at the copier: the first two in the order they came, each with the worker
 * that asks for it. A worker is the prompt's story's worker when that story is at work, or else the
 * worker at work in the prompt's session, or else a teal robot with no story. A worker asks for one
 * prompt at a time, and a worker already called away, as to the glass office, doesn't ask.
 * @param {import('../../shared/state.js').Prompt[]} prompts
 * @param {{ story: string, tier: 'T1' | 'T2' | 'T3', session?: string }[]} working  The stories at
 *   work, each with its worker's session when known.
 * @param {Set<string>} [away]  The stories whose workers are called away.
 * @returns {Asker[]}
 */
export function atCopier(prompts, working, away = new Set()) {
  const ordered = [...prompts].sort((a, b) => (a.since < b.since ? -1 : a.since > b.since ? 1 : a.session < b.session ? -1 : a.session > b.session ? 1 : 0))
  /** @type {Set<string>} */
  const taken = new Set(away)
  return ordered.slice(0, ASKERS).map((prompt, place) => {
    const free = working.filter((w) => !taken.has(w.story))
    const worker = (prompt.story === null ? undefined : free.find((w) => w.story === prompt.story)) ?? free.find((w) => w.session !== undefined && w.session === prompt.session)
    if (worker === undefined) return { session: prompt.session, story: null, tier: 'T1', place }
    taken.add(worker.story)
    return { session: prompt.session, story: worker.story, tier: worker.tier, place }
  })
}

/**
 * The walk from a point on the floor to a place at the copier, in plate pixels: down to the lane
 * below the desks, along it, and across to the copier, as the prototype walks it. A point already
 * by the copier goes straight across.
 * @param {Point} from
 * @param {Point} to
 * @returns {Point[]}
 */
export function toCopier(from, to) {
  /** @type {Point[]} */
  const route = [from]
  if (!(from.y >= LANE && from.x <= to.x + LANE_OFF + 30 && from.y <= to.y + 30)) route.push({ x: from.x, y: LANE }, { x: to.x + LANE_OFF, y: LANE })
  route.push(to)
  return route.filter((p, i) => i === 0 || p.x !== route[i - 1].x || p.y !== route[i - 1].y)
}

/**
 * How far a worker asking at the copier lifts its sheet at a moment, in its own pixels: a call, so
 * it keeps moving, gently under reduced motion.
 * @param {number} ms  How long it has asked, in milliseconds.
 * @param {boolean} [reduced]
 */
export function askBob(ms, reduced = false) {
  const m = motion('worker.ask', { reduced })
  return swing(ms, m) * ASK * m.amplitude
}

/**
 * How bright the copier's red light is at a moment, as alpha, while any prompt waits.
 * @param {number} ms
 * @param {boolean} [reduced]
 */
export function copierGlow(ms, reduced = false) {
  const m = motion('worker.ask', { reduced })
  return GLOW + BLINK * m.amplitude * (2 * swing(ms, m) - 1)
}
