// The tab's title and icon (REQ-SIGNALS-006, spec/architecture.md, "The tab"). Browsers pause
// frames in background tabs, so there the tab carries the signal: the title reads `Harbor`, or
// `(N) Harbor` while N things wait across all projects, and the icon, drawn here on a canvas, carries
// a mark while anything waits. Harbor asks for no notification permission and plays no sound.
import { PALETTE } from './office/palette.js'

export const NAME = 'Harbor'

/**
 * How many things wait on the human across all projects: each parked question, each T3 story
 * awaiting review and each session waiting on a permission prompt.
 * @param {{ questions?: unknown[], reviews?: unknown[], prompts?: unknown[] }[]} projects
 * @returns {number}
 */
export function waiting(projects) {
  return projects.reduce(
    (sum, { questions = [], reviews = [], prompts = [] }) => sum + questions.length + reviews.length + prompts.length,
    0,
  )
}

/**
 * The tab's title while n things wait.
 * @param {number} n
 * @returns {string}
 */
export function title(n) {
  return n > 0 ? `(${n}) ${NAME}` : NAME
}

/** @param {number} colour */
const css = (colour) => `#${colour.toString(16).padStart(6, '0')}`

/**
 * Draws the icon: a desk with its screen aglow, in the office's colours, and a coral dot on the
 * screen's corner, ringed in paper, while anything waits.
 * @param {HTMLCanvasElement} canvas  32 by 32.
 * @param {boolean} marked
 */
function draw(canvas, marked) {
  const g = canvas.getContext('2d')
  if (g === null) return
  g.clearRect(0, 0, 32, 32)
  g.fillStyle = css(PALETTE.backdrop)
  g.beginPath()
  g.roundRect(0, 0, 32, 32, 6)
  g.fill()
  g.fillStyle = css(PALETTE.desk)
  g.fillRect(3, 22, 26, 4)
  g.fillRect(5, 26, 3, 4)
  g.fillRect(24, 26, 3, 4)
  g.fillStyle = css(PALETTE.screen)
  g.fillRect(7, 7, 18, 12)
  g.fillRect(15, 19, 2, 3)
  g.fillStyle = css(PALETTE.glow)
  g.fillRect(9, 9, 14, 8)
  if (!marked) return
  g.fillStyle = css(PALETTE.paper)
  g.beginPath()
  g.arc(25, 7, 6, 0, Math.PI * 2)
  g.fill()
  g.fillStyle = css(PALETTE.call)
  g.beginPath()
  g.arc(25, 7, 4.5, 0, Math.PI * 2)
  g.fill()
}

/**
 * Takes over the document's title and icon, and returns how to show what waits.
 * @param {Document} doc
 * @returns {{ show: (n: number) => void }}
 */
export function tab(doc) {
  const canvas = doc.createElement('canvas')
  canvas.width = 32
  canvas.height = 32
  const link = doc.createElement('link')
  link.rel = 'icon'
  link.type = 'image/png'
  doc.head.append(link)
  /** Whether the icon now carries the mark, or null before it is first drawn. @type {boolean | null} */
  let drawn = null
  const show = (/** @type {number} */ n) => {
    doc.title = title(n)
    const marked = n > 0
    if (marked === drawn) return
    drawn = marked
    draw(canvas, marked)
    link.href = canvas.toDataURL('image/png')
    link.dataset.marked = String(marked)
  }
  show(0)
  return { show }
}
