// The office's stage: one 2D canvas, drawn from the art at /art/ and the sprite table bundled from
// client/art/sprites.json (docs/art/README.md). Each active project is an office, the plate with an
// empty chair at each of its four desks, tiled on a grid ordered by name with every office in view
// (REQ-DOCKS-001, REQ-DOCKS-003). With no active project it draws one dimmed empty office
// (REQ-DOCKS-006). Zoomed in, one office fills the page at the plate's shape, and the split draws two
// side by side, each as when zoomed in (REQ-DOCKS-004, REQ-DOCKS-005). An office arrives with a
// motion played once and leaves quietly as it fades, each as loud as the vocabulary says. Each
// office's whiteboard holds a sticky note per story of the phase under way, ticked as its stories
// land (REQ-SHIPS-001 to REQ-SHIPS-003). The team lead and the QA lead stand at rest, and each story
// at work is its worker typing at its desk, which cheers when its story lands (REQ-SHIPS-006,
// REQ-SHIPS-007; the rules are client/office/crew.js). A frame is drawn only while something moves
// or the state changes. It says what it drew at a point, the whiteboard, a sticky note or a worker,
// each where it stands at rest, for its label (REQ-LABELS-002). It says where each worker's bubble
// points: over its screen while it types, over its head while it cheers, and none while it walks
// (DECISION-024; client/office/bubbles.js). While a question is parked, the team lead talks on its
// headset, rocking on its wheel, and the desk phone in the glass office blinks its light, a call at
// loudness 4, with a ringed bubble over the lead's head (REQ-SIGNALS-002, REQ-SIGNALS-005; the rules
// are client/office/calls.js). A T3 story awaiting review is its worker reading at the glass office,
// a call under a ringed bubble, two side by side in plan order: a worker still at work on the story
// walks there from its desk, which keeps its chair while its screen dims, and any other walks in
// from the front of the room; once the review is gone, it walks back to its desk if it still works,
// or else off the floor (REQ-SIGNALS-003). A session waiting on a permission prompt sends a worker to
// the copier to ask, a call under a ringed bubble, two side by side in the order the prompts came,
// while the copier's red light blinks: the prompt's story's worker, or else the worker at work in its
// session, or else a teal robot with no story. A worker at its desk walks there from it, along the
// lane below the desks, and back once the prompt clears, or else off the floor (REQ-SIGNALS-004).
// While a gate run is under way, the QA lead walks to the desk of the worker at work in the run's
// session, or stays at its own spot, and writes on its clipboard, work that stands still under
// reduced motion; when the result comes it gives a thumbs up or holds up a red cross, once, and
// walks back (REQ-SIGNALS-001; the rules are client/office/gates.js). While a phase is in its
// retro, the crew gathers in the lounge: a teal, an amber and a coral robot walk in from the front,
// and the team lead rolls down to point and talk beside them, work that stands still under reduced
// motion; a question still puts the lead on the phone there. Once phase-N is tagged, the crew goes
// back (REQ-SHIPS-004; the rules are client/office/retro.js). Once the project is tagged `mvp`, the
// office holds launch day: bunting goes up on the back wall, the balloons and the cake come out,
// confetti falls once and every robot in the room cheers once, an event below anything that calls;
// the props then stay at rest, and a page loaded later draws them so (REQ-SHIPS-005; the rules are
// client/office/launch.js). When any of its art fails to load, it stops drawing and says so once,
// and the page shows the same state as a list instead (REQ-DOCKS-007).
import sprites from '../art/sprites.json' with { type: 'json' }
import { frames } from './frames.js'
import { atWork, motion, notesOf, once, phaseUnderWay } from '../vocabulary.js'
import { askerBubbleAt, bubbleAt, leadBubbleAt, readerBubbleAt } from './bubbles.js'
import { along, askBob, atCopier, atGlass, copierGlow, onPhone, phoneGlow, readBob, routeLength, talkBob, toCopier, toGlass } from './calls.js'
import { codeFor, firstDesks, seat, seatOf, seedOf, typingFrame } from './crew.js'
import { checkAt, checked, resultOf, showLift, showPose, toCheck, writeBob } from './gates.js'
import { PROPS, cheerAt, comeOut, confetti, launched, partyLength, propAt, propBox } from './launch.js'
import { GATHERED, hostPose, inRetro, leadAt, rollIn, walkIn } from './retro.js'
import { BOARD, COPIER, COPIER_LIGHT, DESKS, DOOR, ENTRY, GLASS, PHONE, PLATE, SPOTS, boardChange, chairAt, chairs, framed, hit, lone, noteGrid, placed, tiles } from './layout.js'

/** The page behind the offices, and the veil that dims the empty office. */
const BACKDROP = '#2a2622'
const VEIL = 'rgb(20 18 16 / 0.55)'
/** How far an office rises as it arrives, and sinks as it leaves, at amplitude 1, as a share of its height. */
const TRAVEL = 0.25
/** How far above an office's front edge its button's top sits, in CSS pixels: its height and a gap. */
const BUTTON = 36
/** The whiteboard's clean face, top to bottom, painted over the notes the plate was drawn with. */
const FACE = ['rgb(211 191 164)', 'rgb(198 176 145)']
/** The ink of a tick. */
const INK = '#2f3b36'
/** How far notes come down as they go, as a share of the board's height. */
const DROP = 0.6
/** How far a worker walks in one cycle of work's rate, in plate pixels, and how many steps it takes. */
const PACE = 180
const STRIDES = 8
/** How high a walking robot bobs on its lifted step, and a cheering one hops, at amplitude 1, in its own pixels. */
const BOB = 1.2
const HOP = 14
/** Of a cheer, the share at its start spent standing up, before the arms go up. */
const RISE = 0.2
/** How much a screen has typed under reduced motion, in seconds of typing: a still screenful. */
const STILL_TYPED = 40
/** How fast code grows on a screen, in characters a second, and its glyphs' width and line height, in plate pixels. */
const CPS = 16
const CH = 1.05
const LH = 3.6
/** A screen's face, and the pass band's teal. */
const SCREEN = '#1d222b'
const PASS = 'rgba(43, 179, 160, 0.94)'
/** The veil over a screen whose worker reads at the glass office. */
const DIM = 'rgba(12, 14, 20, 0.62)'
/** A worker's walk across the room, seen from the side, each leg taking its turn. */
const SIDE = Object.freeze(['stride-a', 'pass-a', 'stride-b', 'pass-b'])
/** The desk phone's light, in the prototype's amber, and the reach of its glow, in plate pixels. */
const LIGHT = '240, 168, 58'
const LIGHT_REACH = 16
/** The copier's light, in the prototype's red. */
const RED = '224, 71, 95'

/**
 * @typedef {object} Whiteboard
 * @property {number | null} n  The phase under way, or null when none is planned.
 * @property {import('../vocabulary.js').Note[]} notes
 * @property {Map<string, number | null>} ticks  Notes being ticked, with when each began by the frame
 *   clock, null until the first frame after.
 * @property {{ old: import('../vocabulary.js').Note[], since: number | null } | null} swap  The notes
 *   coming down as the next phase's go up, while they do.
 */

/**
 * A worker's robot on the office floor.
 * @typedef {object} Walker
 * @property {string} story  Its story, or '' for a teal robot with no story, asking at the copier.
 * @property {import('./layout.js').Seat} seat  Its robot, by its story's tier.
 * @property {number} desk  Its desk, from the left.
 * @property {'in' | 'seated' | 'cheer' | 'out' | 'go' | 'review' | 'ask'} mode  Walking in from the
 *   front of the room, typing at its desk, cheering in front of its chair, walking off toward the
 *   front, walking its route to or from the glass office or the copier, reading at the glass office
 *   while its story awaits review, or asking at the copier while a session waits on a prompt.
 * @property {number | null} since  When its mode began, by the frame clock; null until the first
 *   frame after.
 * @property {number} from  How far down the room it starts walking off from, in plate pixels.
 * @property {number} began  When its worker began, in epoch milliseconds, which its screen's code
 *   grows from.
 * @property {{ x: number, y: number }[]} [route]  Its walk while it goes, in plate pixels.
 * @property {'review' | 'ask' | 'sit' | 'gone'} [next]  What it does at its walk's end: read at the
 *   glass office, ask at the copier, sit at its desk, or be gone.
 * @property {number} [place]  Its place at the glass office or the copier, from the left, while it
 *   reads or asks there.
 * @property {string} [prompt]  The session it asks for, while it asks at the copier or walks there.
 */

/**
 * What a desk's screen shows: nothing, its worker's code, a landed story's code under a pass, or
 * its worker's code dimmed while it reads at the glass office or asks at the copier.
 * @typedef {{ mode: 'dark' | 'code' | 'pass' | 'dim', story: string | null, typed: number }} Screen
 */

/**
 * An office's workers.
 * @typedef {object} Crew
 * @property {import('./crew.js').Desk[]} desks  Who has each desk, by the rules.
 * @property {import('./layout.js').Seat[]} chairs  The chair drawn at each desk while no robot sits in it.
 * @property {Walker[]} robots
 * @property {Screen[]} screens
 * @property {import('../vocabulary.js').AtWork[]} working  The stories at work, as of the last state.
 * @property {Set<string>} landed  The stories landed, as of the last state.
 * @property {Map<string, number>} began  When each story's worker began, in epoch milliseconds.
 * @property {boolean} calling  Whether its team lead is on the phone, as of the last state.
 * @property {{ story: string, tier: 'T1' | 'T2' | 'T3', place: number }[]} glass  The reviews that
 *   stand at the glass office, as of the last state, each with its place there.
 * @property {import('./calls.js').Asker[]} copier  The prompts that stand at the copier, as of the
 *   last state, each with its worker and its place there.
 * @property {QaLead} qa  Its QA lead.
 * @property {Retro} retro  Its crew at the retro in the lounge.
 * @property {Launch} launch  Its launch day.
 */

/**
 * An office's launch day (REQ-SHIPS-005).
 * @typedef {object} Launch
 * @property {'none' | 'party' | 'up'} mode  No props, before the project is tagged `mvp`; launch day
 *   playing, once; or its props up, at rest.
 * @property {number | null} since  When launch day began, by the frame clock; null until the first
 *   frame after.
 */

/**
 * An office's crew at a retro (REQ-SHIPS-004).
 * @typedef {object} Retro
 * @property {'away' | 'in' | 'here' | 'out'} mode  Not gathered, the lead at its spot; gathering in
 *   the lounge; gathered there; or going back.
 * @property {number | null} since  When its mode began, by the frame clock; null until the first
 *   frame after.
 */

/**
 * An office's QA lead (REQ-SIGNALS-001).
 * @typedef {object} QaLead
 * @property {'rest' | 'go' | 'check' | 'show'} mode  Standing at its spot, walking, writing on its
 *   clipboard while a run is under way, or showing the result of the run it checked.
 * @property {{ x: number, y: number }} at  Where it stands, while it isn't walking, in plate pixels.
 * @property {{ x: number, y: number }} target  Where it checks the run under way, or its spot.
 * @property {{ x: number, y: number }[]} route  Its walk while it goes.
 * @property {number | null} since  When its mode began, by the frame clock; null until the first
 *   frame after.
 * @property {string | null} run  The run it checks, by detail.run, as of the last state.
 * @property {import('../../shared/state.js').GateResult | null} result  The result it shows, while
 *   it shows one.
 */

/**
 * @typedef {object} Office
 * @property {string} id
 * @property {Whiteboard} board
 * @property {Crew} crew
 * @property {{ x: number, y: number, width: number, height: number }} box  Its place, in CSS pixels.
 * @property {'arriving' | 'rest' | 'leaving'} phase
 * @property {number | null} since  When its arrival or leaving began, by the frame clock; null until
 *   the first frame after it began.
 * @property {boolean} seen  Whether it was in view when it began to leave, so it fades where it was.
 */

/**
 * A project as the stage draws it.
 * @typedef {{ id: string, name: string, mvp?: boolean, phases: import('../../shared/state.js').Phase[], workers?: { story: string, since: string, session?: string }[], questions?: import('../../shared/state.js').Question[], reviews?: import('../../shared/state.js').Review[], prompts?: import('../../shared/state.js').Prompt[], gateRuns?: import('../../shared/state.js').GateRun[], gateResults?: import('../../shared/state.js').GateResult[] }} Staged
 */

/**
 * @typedef {object} OfficeStage
 * @property {(projects: Staged[], options: { initial: boolean }) => void} update
 *   An office for each project: new ones arrive, unless this is the first state, which is drawn at
 *   rest, and gone ones leave. Each office's whiteboard holds the phase under way: a story that lands
 *   ticks its note, and a change of phase takes the notes down and puts the next phase's up.
 * @property {(id: string) => { x: number, y: number } | null} anchor  Where the top of an office's
 *   button goes, by the middle of its front edge, in CSS pixels; null for an office that is leaving.
 * @property {(ids: string[] | null) => void} show  The offices in view, in the order they are placed,
 *   or null for the overview's every office.
 * @property {(x: number, y: number) => string | null} pick  The office in view at a point in CSS
 *   pixels, or null where there is none.
 * @property {(x: number, y: number) => import('../vocabulary.js').OfficeThing | null} at  What an
 *   office in view draws at a point in CSS pixels: its whiteboard, a sticky note, a worker, the
 *   team lead on the phone, a worker reading at the glass office or one asking at the copier, or
 *   the QA lead checking the gates or showing their result, found where each stands at rest; null
 *   for anything else.
 * @property {() => import('./bubbles.js').Point[]} bubbles  Where each bubble points as of the
 *   last frame, by the middle of its foot, in CSS pixels: over a typing worker's screen, a cheering
 *   one's head, or the head of the team lead on the phone, of a worker reading at the glass office
 *   or of one asking at the copier, which call, in each office drawn. None
 *   for a walking worker or a leaving office.
 * @property {() => void} resize
 */

/** @typedef {Record<string, import('./layout.js').SpriteEntry>} SpriteTable */
const TABLE = /** @type {SpriteTable} */ (/** @type {unknown} */ (sprites))
const CHAIRS = chairs(TABLE)
/** Every sprite the office draws, loaded up front so a robot never waits on its image. */
const SPRITES = [
  ...['t1', 't2', 't3'].flatMap((t) => ['chair', 'type-a', 'type-b', 'type-c', 'stand', 'cheer', 'read', 'walk-up', 'walk-down'].map((pose) => `${t}-${pose}`)),
  ...['w1', 'w2', 'w3'].flatMap((w) => SIDE.map((step) => `${w}-${step}`)),
  'lead-stand',
  'lead-talk',
  'lead-point',
  'lead-roll',
  'lead-cheer',
  ...PROPS.map((prop) => prop.sprite),
  ...['stand', 'write', 'thumbs', 'cross', 'stride', 'pass'].map((pose) => `qa-${pose}`),
]
/** The QA lead's walk across the room, seen from the side. */
const QA_SIDE = Object.freeze(['qa-stride', 'qa-pass'])

/**
 * A project's whiteboard: the phase under way and its notes.
 * @param {Staged} project
 * @returns {import('./layout.js').Board}
 */
function boardOf(project) {
  const phase = phaseUnderWay(project.phases, project.workers ?? [])
  return phase === null ? { n: null, notes: [] } : { n: phase.n, notes: notesOf(phase) }
}

/**
 * Starts the office's stage on a canvas.
 * @param {HTMLCanvasElement} canvas
 * @param {{ reduced: () => boolean, onFrame: () => void, onBroken: () => void }} options  reduced:
 *   whether the person prefers reduced motion now; onFrame: called after each frame is drawn;
 *   onBroken: called once when an image of the art fails to load, after which nothing is drawn.
 * @returns {OfficeStage}
 * @throws {Error} When the canvas can't give a 2D context.
 */
export function stage(canvas, { reduced, onFrame, onBroken }) {
  const context = canvas.getContext('2d')
  if (context === null) throw new Error('The office needs a 2D canvas.')
  const ctx = context

  /** Whether an image of the art failed to load, so the office can't be drawn. */
  let broken = false
  const breaks = () => {
    if (broken) return
    broken = true
    onBroken()
  }
  /** @type {Map<string, HTMLImageElement>} */
  const images = new Map()
  /** @param {string} name */
  const image = (name) => {
    let img = images.get(name)
    if (img === undefined) {
      img = new Image()
      img.decoding = 'async'
      img.addEventListener('load', () => loop.wake())
      img.addEventListener('error', breaks)
      img.src = `/art/${name}.png`
      images.set(name, img)
    }
    return img
  }
  const plate = image('office')
  for (const name of SPRITES) image(name)

  /** @type {Map<string, Office>} */
  const offices = new Map()
  /** Whether any project is active, so the empty office isn't drawn before the first state. */
  let known = false
  let width = 0
  let height = 0

  const size = () => {
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    width = canvas.clientWidth
    height = canvas.clientHeight
    const w = Math.max(1, Math.round(width * dpr))
    const h = Math.max(1, Math.round(height * dpr))
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w
      canvas.height = h
    }
    return dpr
  }

  /** @type {{ id: string, name: string }[]} */
  let projects = []
  /** The offices in view, or null for the overview. @type {string[] | null} */
  let inView = null
  /** Where each worker's bubble points, as of the last frame. @type {ReturnType<OfficeStage['bubbles']>} */
  let marks = []

  /** @param {Office} office  Whether it is drawn: in view, or fading where it was seen. */
  const visible = (office) => (office.phase === 'leaving' ? office.seen : inView === null || inView.includes(office.id))

  /** Puts each office still in the state at its place in the view. Leaving offices keep theirs. */
  const lay = () => {
    for (const place of framed(projects, inView, width, height)) {
      const office = offices.get(place.id)
      if (office !== undefined && office.phase !== 'leaving') office.box = { x: place.x, y: place.y, width: place.width, height: place.height }
    }
  }

  /**
   * Draws an office's room, the plate, its whiteboard and its chairs, in a box.
   * @param {{ x: number, y: number, width: number, height: number }} box
   * @param {number} alpha
   * @param {number} lift  How far it sits below its place, in CSS pixels.
   * @param {Whiteboard | null} board  The office's whiteboard, or null for the empty office.
   * @param {Crew | null} crew  The office's workers, or null for the empty office.
   * @param {number} now  The frame clock.
   * @param {string | null} [id]  The office's id, whose workers' bubbles are marked when given.
   * @returns {boolean} Whether its whiteboard or its workers still move.
   */
  const room = (box, alpha, lift, board, crew, now, id = null) => {
    if (alpha <= 0) return false
    const scale = box.width / PLATE.width
    ctx.save()
    ctx.globalAlpha = alpha
    ctx.translate(box.x, box.y + lift)
    ctx.scale(scale, scale)
    ctx.beginPath()
    ctx.rect(0, 0, PLATE.width, PLATE.height)
    ctx.clip()
    if (ready(plate)) ctx.drawImage(plate, 0, 0, PLATE.width, PLATE.height)
    else {
      ctx.fillStyle = '#e9e1cf'
      ctx.fillRect(0, 0, PLATE.width, PLATE.height)
    }
    let moving = whiteboard(ctx, board, now, reduced())
    if (crew === null) {
      for (const chair of CHAIRS) {
        shadow(ctx, chair.x, chair.y, chair.shadow)
        const img = images.get(chair.sprite)
        if (img !== undefined && ready(img)) ctx.drawImage(img, chair.left, chair.top, chair.width, chair.height)
      }
    } else {
      /** @type {{ story: string | null, call: boolean, x: number, y: number, prompt?: string }[]} */
      const points = []
      if (floor(crew, now, points)) moving = true
      if (id !== null) for (const p of points) marks.push({ office: id, story: p.story, call: p.call, x: box.x + p.x * scale, y: box.y + lift + p.y * scale })
    }
    ctx.restore()
    return moving
  }

  /**
   * Draws a sprite at its robot's size, by an anchor on the floor, on a context in plate pixels.
   * @param {import('./layout.js').Robot} who
   * @param {string} name
   * @param {{ x: number, y: number }} at
   * @param {'body' | 'foot'} anchor
   * @param {{ face?: number, bob?: number }} [options]  face: -1 mirrors it; bob: how far it lifts,
   *   in its own pixels.
   */
  const sprite = (who, name, at, anchor, { face = 1, bob = 0 } = {}) => {
    const p = placed(TABLE, who, name, at, anchor)
    const img = image(name)
    if (!ready(img)) return
    ctx.save()
    ctx.translate(at.x, at.y - bob * p.scale)
    if (face < 0) ctx.scale(-1, 1)
    ctx.drawImage(img, -p.ax * p.scale, -p.foot * p.scale, p.width, p.height)
    ctx.restore()
  }

  /**
   * Where a walker is and what it shows at a moment, and whether its walk or its cheer is done.
   * @param {Walker} robot
   * @param {number} now
   * @param {boolean} still
   * @returns {{ name: string, at: { x: number, y: number }, anchor: 'body' | 'foot', face: number, bob: number, done: boolean }}
   */
  const pose = (robot, now, still) => {
    const desk = DESKS[robot.desk]
    if (robot.since === null) robot.since = now
    const local = now - robot.since
    if (robot.mode === 'review') {
      // It reads its story's diff in front of the glass office, a call, so it keeps moving.
      return { name: `${robot.seat}-read`, at: GLASS[robot.place ?? 0], anchor: 'body', face: 1, bob: readBob(local, still), done: false }
    }
    if (robot.mode === 'ask') {
      // It asks at the copier with its sheet, a call, so it keeps moving.
      return { name: `${robot.seat}-read`, at: COPIER[robot.place ?? 0], anchor: 'body', face: 1, bob: askBob(local, still), done: false }
    }
    if (robot.mode === 'go') {
      const route = robot.route ?? [ENTRY]
      const cycle = once(motion('worker.walk', { reduced: still }))
      const length = routeLength(route)
      const w = along(route, cycle === 0 ? length : (local / cycle) * PACE)
      const step = cycle === 0 ? 0 : Math.floor(local / (cycle / STRIDES))
      const at = { x: w.x, y: w.y }
      // Across the room it is seen from the side, each leg taking its turn; up and down, as walking in.
      if (w.heading === 'across') return { name: `w${robot.seat.slice(1)}-${SIDE[step % SIDE.length]}`, at, anchor: 'body', face: w.face, bob: 0, done: w.done }
      return { name: `${robot.seat}-walk-${w.heading}`, at, anchor: 'body', face: step % 2 ? -1 : 1, bob: step % 2 ? 0 : BOB, done: w.done }
    }
    if (robot.mode === 'seated') {
      const name = `${robot.seat}-${typingFrame(local + robot.desk * 140, still)}`
      return { name, at: desk.seat, anchor: 'foot', face: 1, bob: 0, done: false }
    }
    if (robot.mode === 'cheer') {
      // A cheer lasts one cycle of an event, held as long under reduced motion, but without the hop.
      const length = once(motion('worker.cheer'))
      const t = Math.min(1, local / length)
      const hop = t < RISE ? 0 : Math.sin(((t - RISE) / (1 - RISE)) * Math.PI) * HOP * motion('worker.cheer', { reduced: still }).amplitude
      return { name: `${robot.seat}-${t < RISE ? 'stand' : 'cheer'}`, at: desk.front, anchor: 'body', face: 1, bob: hop, done: t >= 1 }
    }
    const cycle = once(motion('worker.walk', { reduced: still }))
    const from = robot.mode === 'in' ? DOOR : robot.from
    const to = robot.mode === 'in' ? desk.front.y : DOOR
    const reach = Math.abs(to - from)
    const walked = cycle === 0 ? reach : Math.min(reach, (local / cycle) * PACE)
    const y = from + Math.sign(to - from) * walked
    const step = cycle === 0 ? 0 : Math.floor(local / (cycle / STRIDES)) % 2
    const name = `${robot.seat}-${robot.mode === 'in' ? 'walk-up' : 'walk-down'}`
    return { name, at: { x: desk.front.x, y }, anchor: 'body', face: step ? -1 : 1, bob: step ? 0 : BOB, done: walked >= reach }
  }

  /**
   * Where the QA lead is and what it shows at a moment, and whether its walk or its showing is done:
   * across the room it is seen from the side, its two frames taking turns; checking, it writes on
   * its clipboard; showing a result, it gives a thumbs up or holds up a red cross for one cycle of an
   * event, held as long without the lift under reduced motion.
   * @param {QaLead} qa
   * @param {number} now
   * @param {boolean} still
   * @returns {{ name: string, at: { x: number, y: number }, face: number, bob: number, done: boolean }}
   */
  const qaPose = (qa, now, still) => {
    if (qa.since === null) qa.since = now
    const local = now - qa.since
    if (qa.mode === 'go') {
      const cycle = once(motion('qa.walk', { reduced: still }))
      const length = routeLength(qa.route)
      const w = along(qa.route, cycle === 0 ? length : (local / cycle) * PACE)
      const step = cycle === 0 ? 0 : Math.floor(local / (cycle / STRIDES))
      // Up or down the room it keeps facing the way it walks across.
      const face = w.heading === 'across' ? w.face : Math.sign(qa.route[qa.route.length - 1].x - qa.route[0].x) || 1
      return { name: QA_SIDE[step % QA_SIDE.length], at: { x: w.x, y: w.y }, face, bob: 0, done: w.done }
    }
    if (qa.mode === 'show' && qa.result !== null) {
      const t = Math.min(1, local / once(motion('qa.result')))
      return { name: showPose(qa.result), at: qa.at, face: 1, bob: showLift(t, still), done: t >= 1 }
    }
    if (qa.mode === 'check') return { name: 'qa-write', at: qa.at, face: 1, bob: writeBob(local, still), done: false }
    return { name: 'qa-stand', at: qa.at, face: 1, bob: 0, done: false }
  }

  /**
   * The QA lead at its walk's end, or put there at once: it checks the run under way, or stands at
   * rest at its spot.
   * @param {QaLead} qa
   */
  const settleQa = (qa) => {
    qa.at = { x: qa.target.x, y: qa.target.y }
    qa.route = []
    qa.mode = qa.run === null ? 'rest' : 'check'
    qa.since = null
  }

  /**
   * Sends the QA lead from where it is to where it checks the run under way, or back to its spot;
   * without walking, as when drawn at rest or under reduced motion, it is there at once. One already
   * on its way there keeps walking.
   * @param {QaLead} qa
   * @param {boolean} jump
   */
  const qaGo = (qa, jump) => {
    const to = qa.target
    const end = qa.route[qa.route.length - 1]
    if (qa.mode === 'go' && !jump && end !== undefined && end.x === to.x && end.y === to.y) return
    const here = qa.mode === 'go' ? qaPose(qa, performance.now(), reduced()).at : qa.at
    if (jump || (here.x === to.x && here.y === to.y)) {
      const mode = qa.run === null ? 'rest' : 'check'
      const since = qa.mode === mode ? qa.since : null
      settleQa(qa)
      qa.since = since
      return
    }
    qa.route = toCheck(here, to)
    qa.mode = 'go'
    qa.since = null
  }

  /**
   * Brings the QA lead to a new state: the result of the run it checked, once it comes, is shown
   * where it stands, once, unless drawn at rest; otherwise it goes to check the newest run under way,
   * at its worker's desk or its own spot, or back to its spot when none is.
   * @param {QaLead} qa
   * @param {Staged} project
   * @param {Crew} crew
   * @param {{ story: string, session?: string }[]} staffed  The stories at work, with their sessions.
   * @param {boolean} rest
   */
  const recheck = (qa, project, crew, staffed, rest) => {
    const runs = project.gateRuns ?? []
    const run = checked(runs)
    const result = rest ? null : resultOf(qa.run, runs, project.gateResults ?? [])
    qa.run = run === null ? null : run.run
    qa.target = checkAt(run, crew.desks, staffed)
    if (result !== null) {
      // It shows the result where it stands, then walks back.
      qa.at = qa.mode === 'go' ? qaPose(qa, performance.now(), reduced()).at : qa.at
      qa.route = []
      qa.mode = 'show'
      qa.result = result
      qa.since = null
      return
    }
    if (qa.mode === 'show') {
      // A result line read after the first, as a failed gate after a passed one, changes what it shows.
      const shown = qa.result === null ? undefined : (project.gateResults ?? []).find((r) => r.run === qa.result?.run)
      if (shown !== undefined) qa.result = shown
      return
    }
    qaGo(qa, rest || reduced())
  }

  /**
   * Draws an office's screens, the phone's light, chairs, workers and leads, back to front, and
   * moves each worker on to its next mode as its walk or its cheer ends.
   * @param {Crew} crew
   * @param {number} now
   * @param {{ story: string | null, call: boolean, x: number, y: number, prompt?: string }[]} points  Gains where
   *   each bubble points, in plate pixels.
   * @returns {boolean} Whether anything still moves.
   */
  const floor = (crew, now, points) => {
    const still = reduced()
    let moving = false
    // Launch day plays once, then its props stay at rest.
    const day = crew.launch
    /** @type {{ t: number, up: boolean, lift: number } | null} */
    let party = null
    if (day.mode === 'party') {
      if (day.since === null) day.since = now
      const t = Math.min(1, (now - day.since) / partyLength())
      if (t >= 1) {
        day.mode = 'up'
        day.since = null
      } else {
        party = { t, ...cheerAt(t, still) }
        moving = true
      }
    }
    /**
     * A robot's cheer on launch day, where it stands: its pose's name and how high it hops.
     * @param {string} stand
     * @param {string} cheer
     */
    const cheering = (stand, cheer) => (party === null ? null : { name: party.up ? cheer : stand, bob: party.lift * HOP })
    if (crew.calling) {
      // A call keeps moving for as long as it lasts, gently under reduced motion.
      moving = true
      glow(ctx, PHONE, phoneGlow(now, still), LIGHT)
    }
    if (crew.copier.length > 0) {
      // While any prompt waits, the copier's red light blinks, a call.
      moving = true
      glow(ctx, COPIER_LIGHT, copierGlow(now, still), RED)
    }
    /** @type {{ y: number, draw: () => void }[]} */
    const items = []
    for (const robot of [...crew.robots]) {
      let p = pose(robot, now, still)
      if (p.done) {
        if (robot.mode === 'in') sit(crew, robot)
        else if (robot.mode === 'cheer') {
          // A landed story awaiting review takes its worker from its cheer to the glass office.
          const reading = crew.glass.find((g) => g.story === robot.story)
          if (reading !== undefined) travel(crew, robot, 'review', { place: reading.place }, still)
          else leave(crew, robot, DESKS[robot.desk].front.y)
          reseat(crew, [], false)
        } else if (robot.mode === 'go') arrive(crew, robot, robot.next ?? 'gone')
        else crew.robots.splice(crew.robots.indexOf(robot), 1)
        if (!crew.robots.includes(robot)) continue
        robot.since = now
        p = pose(robot, now, still)
      }
      if (robot.mode !== 'seated' || !still) moving = true
      // On launch day a worker at its desk gets up in front of its chair and cheers, once.
      const cheer = robot.mode === 'seated' ? cheering(`${robot.seat}-stand`, `${robot.seat}-cheer`) : null
      if (cheer !== null) p = { ...p, name: cheer.name, at: DESKS[robot.desk].front, anchor: 'body', bob: cheer.bob }
      const { name, at, anchor, face, bob } = p
      if (robot.mode === 'review') points.push({ story: robot.story, call: true, ...readerBubbleAt(TABLE, robot.seat, robot.place ?? 0) })
      else if (robot.mode === 'ask') points.push({ story: robot.story === '' ? null : robot.story, call: true, prompt: robot.prompt ?? '', ...askerBubbleAt(TABLE, robot.seat, robot.place ?? 0) })
      else if (robot.mode !== 'go') {
        const point = bubbleAt(TABLE, robot, p, DESKS[robot.desk].screen)
        if (point !== null) points.push({ story: robot.story, call: false, ...point })
      }
      const seated = robot.mode === 'seated' && cheer === null
      items.push({
        y: at.y + 0.5,
        draw: () => {
          const s = placed(TABLE, robot.seat, name, at, anchor)
          shadow(ctx, at.x, at.y, ((seated ? 50 : 38) * s.scale) / s.k)
          sprite(robot.seat, name, at, anchor, { face, bob })
        },
      })
    }
    DESKS.forEach((desk, i) => {
      screen(crew.screens[i], desk.screen, i, now, still, crew)
      if (party === null && crew.robots.some((r) => r.desk === i && r.mode === 'seated')) return
      const chair = chairAt(TABLE, i, crew.chairs[i])
      items.push({
        y: chair.y,
        draw: () => {
          shadow(ctx, chair.x, chair.y, chair.shadow)
          const img = image(chair.sprite)
          if (ready(img)) ctx.drawImage(img, chair.left, chair.top, chair.width, chair.height)
        },
      })
    })
    {
      // The crew at the retro, and the team lead, at its spot or in the lounge.
      const r = crew.retro
      if (r.since === null) r.since = now
      const local = now - r.since
      const talking = crew.calling
      const gathered = r.mode === 'in' || r.mode === 'here'
      // The team lead on the phone talks on its headset, rocking on its wheel, wherever it stands; its
      // bubble is over where it stands at rest, so it holds still while it rocks or rolls.
      if (talking) points.push({ story: null, call: true, ...leadBubbleAt(TABLE, leadAt(gathered)) })
      /**
       * @param {import('./layout.js').Robot} who
       * @param {string} name
       * @param {{ x: number, y: number }} at
       * @param {number} face
       * @param {number} bob
       */
      const figure = (who, name, at, face, bob) =>
        items.push({
          y: at.y + 0.5,
          draw: () => {
            const s = placed(TABLE, who, name, at, 'body')
            shadow(ctx, at.x, at.y, (38 * s.scale) / s.k)
            sprite(who, name, at, 'body', { face, bob })
          },
        })
      if (r.mode === 'in' || r.mode === 'out') {
        // The crew walks in from the front, or back off it, and the lead rolls down, or back up.
        moving = true
        const back = r.mode === 'out'
        const cycle = once(motion('worker.walk', { reduced: still }))
        const step = cycle === 0 ? 0 : Math.floor(local / (cycle / STRIDES)) % 2
        let done = true
        for (const g of GATHERED) {
          const route = back ? walkIn(g.at).reverse() : walkIn(g.at)
          const w = along(route, cycle === 0 ? routeLength(route) : (local / cycle) * PACE)
          if (!w.done) done = false
          figure(g.seat, `${g.seat}-walk-${back ? 'down' : 'up'}`, w, step ? -1 : 1, step ? 0 : BOB)
        }
        const roll = once(motion('lead.roll', { reduced: still }))
        const route = back ? rollIn().reverse() : rollIn()
        const w = along(route, roll === 0 ? routeLength(route) : (local / roll) * PACE)
        if (!w.done) done = false
        figure('lead', 'lead-roll', w, 1, 0)
        if (done) {
          r.mode = back ? 'away' : 'here'
          r.since = now
        }
      } else if (r.mode === 'here') {
        // The crew stands in the lounge while the lead, facing it, points and talks.
        // On launch day they cheer, once; the lead on the phone keeps talking.
        for (const g of GATHERED) {
          const c = cheering(`${g.seat}-stand`, `${g.seat}-cheer`)
          figure(g.seat, c?.name ?? `${g.seat}-stand`, g.at, 1, c?.bob ?? 0)
        }
        const c = talking ? null : cheering('lead-stand', 'lead-cheer')
        const name = talking ? 'lead-talk' : (c?.name ?? hostPose(local, still))
        figure('lead', name, leadAt(true), -1, talking ? talkBob(now, still) : (c?.bob ?? 0))
        if (!still) moving = true
      } else {
        const c = talking ? null : cheering('lead-stand', 'lead-cheer')
        figure('lead', talking ? 'lead-talk' : (c?.name ?? 'lead-stand'), SPOTS.lead, 1, talking ? talkBob(now, still) : (c?.bob ?? 0))
      }
    }
    {
      // The QA lead checks the gates, shows their result, walks, or stands at rest.
      let q = qaPose(crew.qa, now, still)
      if (q.done) {
        if (crew.qa.mode === 'go') settleQa(crew.qa)
        else if (crew.qa.mode === 'show') {
          crew.qa.result = null
          crew.qa.mode = 'rest'
          qaGo(crew.qa, still)
        }
        crew.qa.since = now
        q = qaPose(crew.qa, now, still)
      }
      if (crew.qa.mode === 'go' || crew.qa.mode === 'show' || (crew.qa.mode === 'check' && !still)) moving = true
      // On launch day the QA lead, standing or checking, gives a thumbs up, once.
      const c = crew.qa.mode === 'rest' || crew.qa.mode === 'check' ? cheering('qa-stand', 'qa-thumbs') : null
      if (c !== null) q = { ...q, name: c.name, bob: c.bob }
      const { name, at, face, bob } = q
      items.push({
        y: at.y + 0.5,
        draw: () => {
          const s = placed(TABLE, 'qa', name, at, 'body')
          shadow(ctx, at.x, at.y, (38 * s.scale) / s.k)
          sprite('qa', name, at, 'body', { face, bob })
        },
      })
    }
    if (day.mode !== 'none') {
      // The bunting on the back wall, and the balloons and the cake in the lounge, coming out or at rest.
      const out = party === null ? 1 : comeOut(party.t, still)
      for (const prop of PROPS) {
        const { at, alpha } = propAt(prop, out)
        items.push({
          y: prop.at.y,
          draw: () => {
            const img = image(prop.sprite)
            if (!ready(img) || alpha <= 0) return
            const box = propBox(TABLE, prop, at)
            ctx.save()
            ctx.globalAlpha *= alpha
            if (prop.sprite !== 'props-bunting') shadow(ctx, at.x, at.y, box.width * 0.4)
            ctx.drawImage(img, box.left, box.top, box.width, box.height)
            ctx.restore()
          },
        })
      }
    }
    items.sort((a, b) => a.y - b.y).forEach((item) => item.draw())
    // The confetti falls over everything, once.
    if (party !== null) {
      for (const piece of confetti(party.t, still)) {
        ctx.save()
        ctx.translate(piece.x, piece.y)
        ctx.rotate(piece.angle)
        ctx.fillStyle = piece.colour
        ctx.fillRect(-piece.w / 2, -piece.h / 2, piece.w, piece.h)
        ctx.restore()
      }
    }
    return moving
  }

  /**
   * Draws a desk's screen: dark, its worker's code growing behind a blinking cursor, or a landed
   * story's code under a pass band.
   * @param {Screen} sc
   * @param {{ x: number, y: number, w: number, h: number }} box
   * @param {number} desk
   * @param {number} now
   * @param {boolean} still
   * @param {Crew} crew
   */
  const screen = (sc, box, desk, now, still, crew) => {
    if (sc.mode === 'dark' || sc.story === null) return
    const typing = sc.mode === 'code'
    const typed = typing ? (still ? STILL_TYPED : Math.max(0, (Date.now() - (crew.began.get(sc.story) ?? Date.now())) / 1000)) : sc.typed
    const cycle = once(motion('worker.type', { reduced: still }))
    const cursor = typing && (cycle === 0 || Math.floor((now + desk * 250) / (cycle / 4)) % 2 === 0)
    ctx.save()
    rounded(ctx, box.x, box.y, box.w, box.h, 1.5)
    ctx.clip()
    ctx.fillStyle = SCREEN
    ctx.fillRect(box.x, box.y, box.w, box.h)
    code(ctx, codeOf(sc.story), box, typed, cursor)
    if (sc.mode === 'dim') {
      ctx.fillStyle = DIM
      ctx.fillRect(box.x, box.y, box.w, box.h)
    }
    if (sc.mode === 'pass') {
      ctx.fillStyle = PASS
      ctx.fillRect(box.x, box.y + box.h - 8, box.w, 8)
      ctx.strokeStyle = '#f4efe2'
      ctx.lineWidth = 1.3
      ctx.lineCap = 'round'
      ctx.lineJoin = 'round'
      const bx = box.x + box.w / 2 - 3
      const by = box.y + box.h - 4
      ctx.beginPath()
      ctx.moveTo(bx, by)
      ctx.lineTo(bx + 2, by + 2)
      ctx.lineTo(bx + 6, by - 2.2)
      ctx.stroke()
    }
    const g = ctx.createLinearGradient(box.x, box.y, box.x + box.w * 0.6, box.y + box.h)
    g.addColorStop(0, 'rgba(255, 255, 255, 0.10)')
    g.addColorStop(0.45, 'rgba(255, 255, 255, 0.02)')
    g.addColorStop(1, 'rgba(255, 255, 255, 0)')
    ctx.fillStyle = g
    ctx.fillRect(box.x, box.y, box.w, box.h)
    ctx.restore()
    if (sc.mode === 'dim') return
    // The screen's glow on the desk below it.
    const gx = box.x + box.w / 2
    const gy = box.y + box.h + 10
    const glow = ctx.createRadialGradient(gx, gy, 0, gx, gy, 36)
    glow.addColorStop(0, sc.mode === 'pass' ? 'rgba(43, 179, 160, 0.20)' : 'rgba(160, 200, 235, 0.14)')
    glow.addColorStop(1, 'rgba(160, 200, 235, 0)')
    ctx.fillStyle = glow
    ctx.fillRect(gx - 36, gy - 36, 72, 72)
  }

  /** @type {Map<string, import('./crew.js').CodeLine[]>} */
  const codes = new Map()
  /** @param {string} story */
  const codeOf = (story) => {
    let lines = codes.get(story)
    if (lines === undefined) {
      lines = codeFor(seedOf(story))
      codes.set(story, lines)
    }
    return lines
  }

  /**
   * A walker sits at its desk: its chair is now the desk's, and its screen shows its code.
   * @param {Crew} crew
   * @param {Walker} robot
   */
  const sit = (crew, robot) => {
    robot.mode = 'seated'
    robot.since = null
    crew.chairs[robot.desk] = robot.seat
    crew.screens[robot.desk] = { mode: 'code', story: robot.story, typed: 0 }
  }

  /**
   * A walker walks off toward the front from where it is; under reduced motion it is gone at once.
   * @param {Crew} crew
   * @param {Walker} robot
   * @param {number} from  How far down the room it is, in plate pixels.
   */
  const leave = (crew, robot, from) => {
    if (reduced()) {
      crew.robots.splice(crew.robots.indexOf(robot), 1)
      return
    }
    robot.mode = 'out'
    robot.since = null
    robot.from = from
  }

  /**
   * Where a worker is now, in plate pixels: in front of its desk while it sits or cheers there, at
   * its place at the glass office while it reads or at the copier while it asks, or else where its
   * walk has got to.
   * @param {Walker} robot
   */
  const whereIs = (robot) => {
    if (robot.mode === 'seated' || robot.mode === 'cheer') return DESKS[robot.desk].front
    if (robot.mode === 'review') return GLASS[robot.place ?? 0]
    if (robot.mode === 'ask') return COPIER[robot.place ?? 0]
    return pose(robot, performance.now(), reduced()).at
  }

  /**
   * Sends a worker on its walk from where it is: to its place at the glass office or the copier,
   * back to its desk, or off the floor, the way it came. Without walking, as when drawn at rest or
   * under reduced motion, it is there at once. Only a worker on its way to the copier asks.
   * @param {Crew} crew
   * @param {Walker} robot
   * @param {'review' | 'ask' | 'sit' | 'gone'} next
   * @param {{ place?: number, desk?: number, prompt?: string }} target  Its place at the glass office
   *   or the copier, or its desk, and the session it asks for.
   * @param {boolean} jump
   */
  const travel = (crew, robot, next, { place, desk, prompt }, jump) => {
    const from = whereIs(robot)
    const byCopier = asking(robot)
    if (next === 'ask') robot.prompt = prompt ?? robot.prompt
    else delete robot.prompt
    if (place !== undefined) robot.place = place
    if (desk !== undefined) robot.desk = desk
    if (jump) {
      arrive(crew, robot, next)
      return
    }
    const to = next === 'review' ? GLASS[robot.place ?? 0] : next === 'ask' ? COPIER[robot.place ?? 0] : next === 'sit' ? DESKS[robot.desk].front : ENTRY
    if (next === 'review') robot.route = toGlass(from, to)
    else if (next === 'ask') robot.route = toCopier(from, to)
    else robot.route = byCopier ? toCopier(to, from).reverse() : toGlass(to, from).reverse()
    robot.mode = 'go'
    robot.next = next
    robot.since = null
  }

  /**
   * A worker at its walk's end: it reads at the glass office, asks at the copier, sits at its desk,
   * or is gone.
   * @param {Crew} crew
   * @param {Walker} robot
   * @param {'review' | 'ask' | 'sit' | 'gone'} next
   */
  const arrive = (crew, robot, next) => {
    if (next === 'review' || next === 'ask') {
      robot.mode = next
      robot.since = null
    } else if (next === 'sit') sit(crew, robot)
    else crew.robots.splice(crew.robots.indexOf(robot), 1)
  }

  /** @param {Walker} robot  Whether it reads at the glass office, or walks there. */
  const reading = (robot) => robot.mode === 'review' || (robot.mode === 'go' && robot.next === 'review')

  /** @param {Walker} robot  Whether it asks at the copier, or walks there. */
  const asking = (robot) => robot.mode === 'ask' || (robot.mode === 'go' && robot.next === 'ask')

  /** @param {Walker} robot  Whether it is called away from its desk, to the glass office or the copier. */
  const called = (robot) => reading(robot) || asking(robot)

  /**
   * A worker at its desk gets up for a call and leaves its chair, and its screen dims.
   * @param {Crew} crew
   * @param {Walker} robot
   */
  const getUp = (crew, robot) => {
    if (robot.mode !== 'seated') return
    crew.chairs[robot.desk] = robot.seat
    const sc = crew.screens[robot.desk]
    if (sc.story === robot.story && sc.mode === 'code') crew.screens[robot.desk] = { mode: 'dim', story: robot.story, typed: reduced() ? STILL_TYPED : Math.max(0, (Date.now() - robot.began) / 1000) }
  }

  /**
   * Brings the reviews to the glass office by the rules: a worker whose review is gone walks back to
   * its desk if its story still works, or else off the floor; a worker whose place there changed
   * walks to its new one; and each review at the glass office without its worker there brings it,
   * from its desk, where its chair stays and its screen dims, from wherever it walks, or else in
   * from the front of the room. A worker still cheering goes once its cheer ends.
   * @param {Crew} crew
   * @param {boolean} rest  Drawn at rest: each is there at once.
   */
  const glass = (crew, rest) => {
    const jump = rest || reduced()
    const places = new Map(crew.glass.map((g) => [g.story, g.place]))
    for (const robot of [...crew.robots]) {
      if (!reading(robot)) continue
      const place = places.get(robot.story)
      if (place !== undefined) {
        if (place !== robot.place) travel(crew, robot, 'review', { place }, jump)
        continue
      }
      const desk = crew.desks.findIndex((d) => d.story === robot.story)
      if (desk >= 0) travel(crew, robot, 'sit', { desk }, jump)
      else travel(crew, robot, 'gone', {}, jump)
    }
    for (const { story, tier, place } of crew.glass) {
      const own = crew.robots.filter((r) => r.story === story)
      if (own.some((r) => reading(r) || r.mode === 'cheer')) continue
      const robot = own[0]
      if (robot !== undefined) {
        // It gets up and leaves its chair; its screen dims.
        getUp(crew, robot)
        travel(crew, robot, 'review', { place }, jump)
        continue
      }
      /** @type {Walker} */
      const fresh = { story, seat: seatOf(tier), desk: crew.desks.findIndex((d) => d.story === story), mode: 'go', since: null, from: DOOR, began: crew.began.get(story) ?? Date.now(), route: [ENTRY], next: 'review', place }
      crew.robots.push(fresh)
      travel(crew, fresh, 'review', { place }, jump)
    }
  }

  /**
   * Brings the prompts to the copier by the rules: a worker whose prompt has cleared, or that no
   * longer asks for it, walks back to its desk if its story still works, or else off the floor; a
   * worker whose place there changed walks to its new one; and each prompt at the copier without its
   * worker there brings it: its story's worker from its desk, where its chair stays and its screen
   * dims, or from wherever it walks, or else a robot in from the front of the room, a teal one when
   * it has no story. A worker still cheering goes once its cheer ends.
   * @param {Crew} crew
   * @param {boolean} rest  Drawn at rest: each is there at once.
   */
  const copier = (crew, rest) => {
    const jump = rest || reduced()
    const asks = new Map(crew.copier.map((a) => [a.session, a]))
    for (const robot of [...crew.robots]) {
      if (!asking(robot)) continue
      const ask = asks.get(robot.prompt ?? '')
      if (ask !== undefined && (ask.story ?? '') === robot.story) {
        if (ask.place !== robot.place) travel(crew, robot, 'ask', { place: ask.place }, jump)
        continue
      }
      const desk = robot.story === '' ? -1 : crew.desks.findIndex((d) => d.story === robot.story)
      if (desk >= 0) travel(crew, robot, 'sit', { desk }, jump)
      else travel(crew, robot, 'gone', {}, jump)
    }
    for (const { session, story, tier, place } of crew.copier) {
      if (crew.robots.some((r) => asking(r) && r.prompt === session)) continue
      if (story !== null) {
        const own = crew.robots.filter((r) => r.story === story)
        if (own.some((r) => called(r) || r.mode === 'cheer')) continue
        const robot = own[0]
        if (robot !== undefined) {
          getUp(crew, robot)
          travel(crew, robot, 'ask', { place, prompt: session }, jump)
          continue
        }
      }
      /** @type {Walker} */
      const fresh = { story: story ?? '', seat: seatOf(tier), desk: story === null ? -1 : crew.desks.findIndex((d) => d.story === story), mode: 'go', since: null, from: DOOR, began: (story === null ? undefined : crew.began.get(story)) ?? Date.now(), route: [ENTRY], next: 'ask', place, prompt: session }
      crew.robots.push(fresh)
      travel(crew, fresh, 'ask', { place, prompt: session }, jump)
    }
  }

  /**
   * Seats the stories at work by the rules: a worker whose story is no longer at work, without a
   * landing, gets up and walks off and its screen goes dark; each landing with no worker seen cheers
   * with a robot of its tier at the first free desk; and each new worker walks in to its desk, or
   * sits at once when the office is drawn at rest or under reduced motion.
   * @param {Crew} crew
   * @param {{ story: string, tier: 'T1' | 'T2' | 'T3' }[]} cheers
   * @param {boolean} rest
   */
  const reseat = (crew, cheers, rest) => {
    const blocked = new Set(crew.robots.filter((r) => r.mode === 'cheer').map((r) => r.desk))
    const result = seat(crew.desks, crew.working, { blocked, cheers })
    crew.desks = result.desks
    for (const { story, desk } of result.left) {
      if (crew.screens[desk].story === story && crew.screens[desk].mode !== 'pass') crew.screens[desk] = { mode: 'dark', story: null, typed: 0 }
      const robot = crew.robots.find((r) => r.story === story && r.desk === desk && (r.mode === 'in' || r.mode === 'seated' || (r.mode === 'go' && r.next === 'sit')))
      if (robot === undefined) continue
      if (robot.mode === 'go') {
        // On its way back from the glass office to a desk that is no longer its own, it walks off.
        travel(crew, robot, 'gone', {}, reduced())
        continue
      }
      const from = robot.mode === 'in' && robot.since !== null ? pose(robot, performance.now(), reduced()).at.y : robot.mode === 'in' ? DOOR : DESKS[desk].front.y
      leave(crew, robot, from)
    }
    for (const taken of result.cheered) {
      crew.chairs[taken.desk] = taken.seat
      crew.screens[taken.desk] = { mode: 'pass', story: taken.story, typed: STILL_TYPED }
      crew.robots.push({ story: taken.story, seat: taken.seat, desk: taken.desk, mode: 'cheer', since: null, from: DOOR, began: Date.now() })
    }
    for (const taken of result.sat) {
      // A worker reading at the glass office, or asking at the copier, stays; the desk waits for it.
      const reader = crew.robots.find((r) => r.story === taken.story && called(r))
      if (reader !== undefined) {
        reader.desk = taken.desk
        continue
      }
      /** @type {Walker} */
      const robot = { story: taken.story, seat: taken.seat, desk: taken.desk, mode: 'in', since: null, from: DOOR, began: crew.began.get(taken.story) ?? Date.now() }
      crew.robots.push(robot)
      if (rest || reduced()) sit(crew, robot)
    }
  }

  /**
   * An office's workers, from the first state it is drawn in, at rest: each story at work seated.
   * @param {Staged} project
   * @returns {Crew}
   */
  const crewOf = (project) => {
    /** @type {Crew} */
    const crew = {
      desks: firstDesks(),
      chairs: DESKS.map((d) => d.chair),
      robots: [],
      screens: DESKS.map(() => ({ mode: /** @type {const} */ ('dark'), story: null, typed: 0 })),
      working: [],
      landed: landedIn(project),
      began: new Map(),
      calling: onPhone(project.questions ?? []),
      glass: [],
      copier: [],
      qa: { mode: 'rest', at: SPOTS.qa, target: SPOTS.qa, route: [], since: null, run: null, result: null },
      retro: { mode: inRetro(project.phases) ? 'here' : 'away', since: null },
      // An office first drawn after its launch has its props up, at rest, with no confetti.
      launch: { mode: launched(project) ? 'up' : 'none', since: null },
    }
    restaff(crew, project, true)
    return crew
  }

  /**
   * Brings an office's workers to a new state: a story that landed makes its worker get up and
   * cheer, its screen showing a pass, or else cheers with a robot of its tier at the first free desk;
   * then the desks are seated by the rules.
   * @param {Crew} crew
   * @param {Staged} project
   * @param {boolean} rest  Drawn at rest: nothing that landed cheers, and new workers sit at once.
   */
  const restaff = (crew, project, rest) => {
    const working = atWork(project.phases, project.workers ?? [])
    for (const w of working) {
      const began = Date.parse(w.since)
      if (!crew.began.has(w.story)) crew.began.set(w.story, Number.isNaN(began) ? Date.now() : began)
    }
    const landed = landedIn(project)
    /** @type {{ story: string, tier: 'T1' | 'T2' | 'T3' }[]} */
    const cheers = []
    if (!rest) {
      for (const story of landed) {
        if (crew.landed.has(story)) continue
        // A worker reading at the glass office or asking at the copier, or walking to or from either,
        // doesn't cheer.
        if (crew.robots.some((r) => r.story === story && (r.mode === 'review' || r.mode === 'ask' || r.mode === 'go'))) continue
        const robot = crew.robots.find((r) => r.story === story && (r.mode === 'in' || r.mode === 'seated'))
        if (robot === undefined) {
          cheers.push({ story, tier: tierIn(project, story) })
          continue
        }
        // It gets up in front of its chair, which stays, and its screen shows the pass.
        const typed = reduced() ? STILL_TYPED : Math.max(0, (Date.now() - robot.began) / 1000)
        crew.screens[robot.desk] = { mode: 'pass', story, typed: robot.mode === 'seated' ? typed : STILL_TYPED }
        crew.chairs[robot.desk] = robot.seat
        robot.mode = 'cheer'
        robot.since = null
      }
    }
    crew.landed = landed
    crew.working = working
    reseat(crew, cheers, rest)
    // Each T3 story awaiting review brings its worker to the glass office.
    crew.glass = atGlass(project.reviews ?? [], (story) => tierIn(project, story))
    glass(crew, rest)
    // Each session waiting on a permission prompt sends a worker to the copier.
    const sessions = project.workers ?? []
    const staffed = working.map((w) => ({ ...w, session: sessions.find((s) => s.story === w.story && s.since === w.since)?.session }))
    crew.copier = atCopier(project.prompts ?? [], staffed, new Set(crew.glass.map((g) => g.story)))
    copier(crew, rest)
    // A gate run under way sends the QA lead to check it.
    recheck(crew.qa, project, crew, staffed, rest)
    // A phase in its retro gathers the crew in the lounge; once it is tagged, the crew goes back.
    regather(crew.retro, inRetro(project.phases), rest || reduced())
    // The mvp tag brings launch day, once; drawn at rest, its props are up at once.
    if (!launched(project)) crew.launch = { mode: 'none', since: null }
    else if (crew.launch.mode === 'none') crew.launch = { mode: rest ? 'up' : 'party', since: null }
    for (const story of [...crew.began.keys()]) if (!working.some((w) => w.story === story)) crew.began.delete(story)
  }

  /**
   * Gathers the crew in the lounge, or sends it back: walking, or there at once when drawn at rest or
   * under reduced motion. A crew already on its way keeps going.
   * @param {Retro} r
   * @param {boolean} wanted  Whether a phase is in its retro.
   * @param {boolean} jump
   */
  const regather = (r, wanted, jump) => {
    const there = r.mode === 'in' || r.mode === 'here'
    if (wanted === there) {
      if (jump) settleRetro(r)
      return
    }
    r.mode = wanted ? (jump ? 'here' : 'in') : jump ? 'away' : 'out'
    r.since = null
  }

  /**
   * The crew at the retro at its walk's end at once: gathered in the lounge, or gone back.
   * @param {Retro} r
   */
  const settleRetro = (r) => {
    if (r.mode === 'in') r.mode = 'here'
    else if (r.mode === 'out') r.mode = 'away'
    else return
    r.since = null
  }

  /**
   * Puts an office's workers at rest at once: those walking in sit, those walking a route are at
   * its end, and those cheering or walking off are gone, leaving their desks free; then each review
   * has its worker at the glass office, and each prompt its worker at the copier.
   * @param {Crew} crew
   */
  const settleCrew = (crew) => {
    let freed = false
    for (const robot of [...crew.robots]) {
      if (robot.mode === 'in') sit(crew, robot)
      else if (robot.mode === 'go') arrive(crew, robot, robot.next ?? 'gone')
      else if (robot.mode === 'cheer' || robot.mode === 'out') {
        crew.robots.splice(crew.robots.indexOf(robot), 1)
        freed = true
      }
    }
    if (freed) reseat(crew, [], true)
    glass(crew, true)
    copier(crew, true)
    // The QA lead is where it checks, or at its spot, and shows nothing.
    if (crew.qa.mode === 'go' || crew.qa.mode === 'show') {
      crew.qa.result = null
      settleQa(crew.qa)
    }
    // The crew at the retro is in the lounge, or back.
    settleRetro(crew.retro)
    // Launch day is over, its props up.
    if (crew.launch.mode === 'party') crew.launch = { mode: 'up', since: null }
  }

  /**
   * Draws one frame.
   * @param {number} now  The frame clock, in milliseconds.
   * @returns {boolean} Whether anything still moves.
   */
  const draw = (now) => {
    marks = []
    if (broken) return false
    const dpr = size()
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.imageSmoothingEnabled = true
    ctx.imageSmoothingQuality = 'high'
    ctx.fillStyle = BACKDROP
    ctx.fillRect(0, 0, width, height)
    let moving = false
    const still = reduced()
    if (known && projects.length === 0) {
      // One dimmed empty office, so the page doesn't look broken or still loading.
      const box = lone(width, height)
      room(box, 1, 0, null, null, now)
      ctx.fillStyle = VEIL
      ctx.fillRect(box.x, box.y, box.width, box.height)
    }
    for (const office of [...offices.values()]) {
      if (!visible(office)) {
        // Out of view, it is at rest at once, or gone, and so is its whiteboard.
        if (office.phase === 'leaving') offices.delete(office.id)
        else if (office.phase === 'arriving') {
          office.phase = 'rest'
          office.since = null
        }
        office.board.ticks.clear()
        office.board.swap = null
        settleCrew(office.crew)
        continue
      }
      // A leaving office's workers carry no bubbles.
      const marked = office.phase !== 'leaving' ? office.id : null
      if (office.phase === 'rest') {
        if (room(office.box, 1, 0, office.board, office.crew, now, marked)) moving = true
        continue
      }
      if (office.since === null) office.since = now
      const m = motion(office.phase === 'arriving' ? 'office.arrive' : 'office.leave', { reduced: still })
      const length = once(m)
      const t = length === 0 ? 1 : Math.min(1, Math.max(0, (now - office.since) / length))
      const travel = office.box.height * TRAVEL * m.amplitude
      if (office.phase === 'arriving') {
        // It rises into its place as it appears, once.
        const ease = 1 - (1 - t) ** 3
        if (room(office.box, ease, (1 - ease) * travel, office.board, office.crew, now, marked)) moving = true
        if (t < 1) moving = true
        else {
          office.phase = 'rest'
          office.since = null
        }
      } else {
        // It fades, sinking a little, and is gone.
        if (room(office.box, 1 - t, t * travel, office.board, office.crew, now)) moving = true
        if (t < 1) moving = true
        else offices.delete(office.id)
      }
    }
    onFrame()
    return moving
  }

  const loop = frames(draw, (callback) => requestAnimationFrame(callback))

  /** @type {OfficeStage['update']} */
  const update = (next, { initial }) => {
    size()
    known = true
    projects = next.map(({ id, name }) => ({ id, name }))
    const boards = new Map(next.map((p) => [p.id, boardOf(p)]))
    const staged = new Map(next.map((p) => [p.id, p]))
    const wanted = new Set(projects.map((p) => p.id))
    for (const office of offices.values()) {
      if (!wanted.has(office.id) && office.phase !== 'leaving') {
        office.seen = visible(office)
        office.phase = 'leaving'
        office.since = null
      }
    }
    for (const place of tiles(projects, width, height)) {
      const office = offices.get(place.id)
      const after = boards.get(place.id) ?? { n: null, notes: [] }
      // A new office, or one that comes back before it had gone, arrives, its whiteboard at rest.
      if (office === undefined || office.phase === 'leaving') {
        const box = { x: place.x, y: place.y, width: place.width, height: place.height }
        const board = { n: after.n, notes: after.notes, ticks: new Map(), swap: null }
        const project = staged.get(place.id) ?? { id: place.id, name: place.name, phases: [] }
        offices.set(place.id, { id: place.id, box, board, crew: crewOf(project), phase: initial ? 'rest' : 'arriving', since: null, seen: false })
        continue
      }
      // A story landing makes its worker cheer; a worker that comes or goes takes or frees a desk.
      const project = staged.get(place.id)
      if (project !== undefined) {
        restaff(office.crew, project, false)
        // A parked question puts the lead on the phone; the last one leaving puts it back at rest.
        office.crew.calling = onPhone(project.questions ?? [])
      }
      // A story landing ticks its note; a new phase under way takes the old one's notes down.
      const { swapped, ticked } = boardChange(office.board, after)
      if (swapped) {
        office.board.swap = { old: office.board.notes, since: null }
        office.board.ticks.clear()
      }
      for (const id of ticked) office.board.ticks.set(id, null)
      office.board.n = after.n
      office.board.notes = after.notes
    }
    lay()
    loop.wake()
  }

  /** @type {OfficeStage['bubbles']} */
  const bubbles = () => marks

  /** @type {OfficeStage['anchor']} */
  const anchor = (id) => {
    const office = offices.get(id)
    if (office === undefined || office.phase === 'leaving' || !visible(office)) return null
    // On the carpet at the front of the room, clear of the whiteboard and the desks.
    return { x: office.box.x + office.box.width / 2, y: office.box.y + office.box.height - BUTTON }
  }

  /** @type {OfficeStage['show']} */
  const show = (ids) => {
    inView = ids === null ? null : [...ids]
    lay()
    loop.wake()
  }

  /** @type {OfficeStage['pick']} */
  const pick = (x, y) => {
    for (const office of offices.values()) {
      if (office.phase === 'leaving' || !visible(office)) continue
      const { box } = office
      if (x >= box.x && x < box.x + box.width && y >= box.y && y < box.y + box.height) return office.id
    }
    return null
  }

  /** @type {OfficeStage['at']} */
  const at = (x, y) => {
    for (const office of offices.values()) {
      if (office.phase === 'leaving' || !visible(office)) continue
      const { box } = office
      if (!(x >= box.x && x < box.x + box.width && y >= box.y && y < box.y + box.height)) continue
      const scale = box.width / PLATE.width
      const tiers = new Map(office.crew.working.map((w) => [w.story, w.tier]))
      // A worker reading at the glass office, or asking at the copier, is found there, not at its desk.
      const away = new Set(office.crew.robots.filter(called).map((r) => r.story))
      const desks = office.crew.desks.map((d) => (d.story === null || away.has(d.story) ? null : { story: d.story, seat: seatOf(tiers.get(d.story) ?? 'T3') }))
      const readers = office.crew.glass.map((g) => ({ story: g.story, seat: seatOf(g.tier) }))
      const askers = office.crew.copier.map((a) => ({ session: a.session, seat: seatOf(a.tier) }))
      const notes = office.board.notes.map((note) => note.id)
      // The QA lead is found where it checks or shows, so its label holds while it walks or writes.
      const { qa: lead } = office.crew
      const showing = lead.mode === 'show' && lead.result !== null ? lead.result : null
      const qa = showing !== null ? { at: lead.at, result: showing.run } : lead.run !== null ? { at: lead.target, result: null } : null
      // The lead on the phone is found where it stands at rest, at its spot or in the lounge.
      const gathered = office.crew.retro.mode === 'in' || office.crew.retro.mode === 'here'
      const found = hit(TABLE, { x: (x - box.x) / scale, y: (y - box.y) / scale }, { notes, desks, board: office.board.n !== null, lead: office.crew.calling, leadAt: leadAt(gathered), readers, askers, qa })
      return found === null ? null : { office: office.id, ...found }
    }
    return null
  }

  const resize = () => {
    size()
    lay()
    loop.wake()
  }

  size()
  loop.wake()
  return { update, anchor, show, pick, at, bubbles, resize }
}

/**
 * Draws a whiteboard's clean face and its notes, on a context in plate pixels: the phase under way's
 * notes, a landed story's ticked and a note being ticked inking its tick; while the phase under way
 * changes, the old notes come down and then the new ones go up. Both are work.
 * @param {CanvasRenderingContext2D} ctx
 * @param {Whiteboard | null} board
 * @param {number} now  The frame clock.
 * @param {boolean} still  The person prefers reduced motion.
 * @returns {boolean} Whether it still moves.
 */
function whiteboard(ctx, board, now, still) {
  ctx.save()
  const face = ctx.createLinearGradient(0, BOARD.y, 0, BOARD.y + BOARD.height)
  face.addColorStop(0, FACE[0])
  face.addColorStop(1, FACE[1])
  ctx.fillStyle = face
  rounded(ctx, BOARD.x, BOARD.y, BOARD.width, BOARD.height, 4)
  ctx.fill()
  ctx.clip()
  let moving = false
  if (board !== null) {
    const swap = board.swap
    if (swap === null) moving = notes(ctx, board.notes, board.ticks, now, still, 1, 0)
    else {
      if (swap.since === null) swap.since = now
      const m = motion('note.swap', { reduced: still })
      const length = once(m)
      const t = length === 0 ? 1 : Math.min(1, Math.max(0, (now - swap.since) / length))
      const drop = BOARD.height * DROP
      // The first half takes the old notes down; the second puts the new ones up.
      const down = Math.min(1, t * 2)
      const up = Math.max(0, t * 2 - 1)
      if (down < 1) notes(ctx, swap.old, new Map(), now, still, 1 - down, down * down * drop)
      if (up > 0) moving = notes(ctx, board.notes, board.ticks, now, still, up, -((1 - up) ** 2) * drop * 0.3)
      if (t < 1) moving = true
      else board.swap = null
    }
  }
  ctx.restore()
  return moving
}

/**
 * Draws a set of sticky notes in the board's grid.
 * @param {CanvasRenderingContext2D} ctx
 * @param {import('../vocabulary.js').Note[]} list
 * @param {Map<string, number | null>} ticks  Notes being ticked; each leaves once its tick is inked.
 * @param {number} now
 * @param {boolean} still
 * @param {number} alpha
 * @param {number} shift  How far below its place each note sits, in plate pixels.
 * @returns {boolean} Whether a tick is still being inked.
 */
function notes(ctx, list, ticks, now, still, alpha, shift) {
  if (alpha <= 0) return false
  let moving = false
  const grid = noteGrid(list.length)
  const length = once(motion('note.tick', { reduced: still }))
  ctx.save()
  ctx.globalAlpha *= alpha
  list.forEach((note, i) => {
    const { x, y, size } = grid[i]
    ctx.save()
    ctx.translate(x + size / 2, y + size / 2 + shift)
    // A slight tilt of its own, so the notes look stuck on by hand.
    ctx.rotate(((((i * 5) % 7) - 3) * Math.PI) / 180)
    ctx.fillStyle = 'rgba(40, 30, 20, 0.22)'
    ctx.fillRect(-size / 2 + size * 0.06, -size / 2 + size * 0.1, size, size)
    ctx.fillStyle = note.colour
    ctx.fillRect(-size / 2, -size / 2, size, size)
    ctx.fillStyle = 'rgba(255, 255, 255, 0.18)'
    ctx.fillRect(-size / 2, -size / 2, size, size * 0.22)
    if (note.ticked) {
      let t = 1
      if (ticks.has(note.id)) {
        let since = ticks.get(note.id) ?? null
        if (since === null) {
          since = now
          ticks.set(note.id, now)
        }
        t = length === 0 ? 1 : Math.min(1, Math.max(0, (now - since) / length))
        if (t < 1) moving = true
        else ticks.delete(note.id)
      }
      tick(ctx, size, t)
    }
    ctx.restore()
  })
  ctx.restore()
  return moving
}

/**
 * A tick on a note centred on the origin, inked as far as t, from 0 to 1.
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} size
 * @param {number} t
 */
function tick(ctx, size, t) {
  if (t <= 0) return
  const a = { x: -0.28 * size, y: 0.02 * size }
  const b = { x: -0.08 * size, y: 0.22 * size }
  const c = { x: 0.3 * size, y: -0.24 * size }
  const first = Math.hypot(b.x - a.x, b.y - a.y)
  const second = Math.hypot(c.x - b.x, c.y - b.y)
  const reach = t * (first + second)
  ctx.strokeStyle = INK
  ctx.lineWidth = Math.max(1, size * 0.12)
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  ctx.beginPath()
  ctx.moveTo(a.x, a.y)
  if (reach <= first) ctx.lineTo(a.x + ((b.x - a.x) * reach) / first, a.y + ((b.y - a.y) * reach) / first)
  else {
    const k = (reach - first) / second
    ctx.lineTo(b.x, b.y)
    ctx.lineTo(b.x + (c.x - b.x) * k, b.y + (c.y - b.y) * k)
  }
  ctx.stroke()
}

/**
 * A rounded rectangle's path.
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} x
 * @param {number} y
 * @param {number} w
 * @param {number} h
 * @param {number} r
 */
function rounded(ctx, x, y, w, h, r) {
  ctx.beginPath()
  ctx.moveTo(x + r, y)
  ctx.arcTo(x + w, y, x + w, y + h, r)
  ctx.arcTo(x + w, y + h, x, y + h, r)
  ctx.arcTo(x, y + h, x, y, r)
  ctx.arcTo(x, y, x + w, y, r)
  ctx.closePath()
}

/**
 * A light's glow, a soft round of its colour, on a context in plate pixels.
 * @param {CanvasRenderingContext2D} ctx
 * @param {{ x: number, y: number }} at
 * @param {number} alpha  How bright it is at its middle.
 * @param {string} colour  Its red, green and blue, as `240, 168, 58`.
 */
function glow(ctx, at, alpha, colour) {
  const g = ctx.createRadialGradient(at.x, at.y, 0, at.x, at.y, LIGHT_REACH)
  g.addColorStop(0, `rgba(${colour}, ${Math.max(0, Math.min(1, alpha)).toFixed(3)})`)
  g.addColorStop(1, `rgba(${colour}, 0)`)
  ctx.fillStyle = g
  ctx.fillRect(at.x - LIGHT_REACH, at.y - LIGHT_REACH, 2 * LIGHT_REACH, 2 * LIGHT_REACH)
}

/**
 * Whether an image has loaded and can be drawn.
 * @param {HTMLImageElement} img
 */
function ready(img) {
  return img.complete && img.naturalWidth > 0
}

/**
 * The soft shadow under a chair, drawn by the page since the art carries none.
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} x
 * @param {number} y
 * @param {number} rx
 */
function shadow(ctx, x, y, rx) {
  const ry = rx * 0.22
  ctx.save()
  ctx.translate(x, y)
  ctx.scale(1, ry / rx)
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx)
  g.addColorStop(0, 'rgba(38, 32, 24, 0.32)')
  g.addColorStop(1, 'rgba(38, 32, 24, 0)')
  ctx.fillStyle = g
  ctx.beginPath()
  ctx.arc(0, 0, rx, 0, Math.PI * 2)
  ctx.fill()
  ctx.restore()
}

/**
 * The stories landed in a project.
 * @param {Staged} project
 */
function landedIn(project) {
  return new Set(project.phases.flatMap((phase) => phase.stories.filter((s) => s.landedAt !== null).map((s) => s.id)))
}

/**
 * A story's tier in a project, T3 when the plan doesn't say.
 * @param {Staged} project
 * @param {string} id
 * @returns {'T1' | 'T2' | 'T3'}
 */
function tierIn(project, id) {
  for (const phase of project.phases) for (const story of phase.stories) if (story.id === id) return story.tier ?? 'T3'
  return 'T3'
}

/**
 * Draws code on a screen as far as it has been typed, the newest line at the bottom, with the cursor
 * at its end when it blinks on.
 * @param {CanvasRenderingContext2D} ctx
 * @param {import('./crew.js').CodeLine[]} lines
 * @param {{ x: number, y: number, w: number, h: number }} box
 * @param {number} typed  Seconds of typing.
 * @param {boolean} cursor
 */
function code(ctx, lines, box, typed, cursor) {
  let left = Math.floor(typed * CPS)
  let i = 0
  for (;;) {
    const line = lines[i % lines.length]
    if (left <= line.chars) break
    left -= line.chars + 4
    i++
  }
  const rows = Math.floor((box.h - 2) / LH)
  const first = Math.max(0, i - rows + 1)
  let endX = box.x + 2.5
  let endY = box.y + 2
  for (let n = first; n <= i; n++) {
    const line = lines[n % lines.length]
    const y = box.y + 2 + (n - first) * LH
    let x = box.x + 2.5 + line.indent * CH
    let budget = n === i ? left - line.indent : Infinity
    if (n === i) {
      endX = x
      endY = y
    }
    for (const token of line.tokens) {
      if (budget <= 0) break
      const len = Math.min(token.len, budget)
      ctx.fillStyle = token.ink
      ctx.fillRect(x, y, len * CH, 1.7)
      if (n === i) endX = x + len * CH + 0.4
      x += (token.len + 1) * CH
      budget -= token.len + 1
    }
  }
  if (cursor) {
    ctx.fillStyle = '#f4efe2'
    ctx.fillRect(Math.min(endX, box.x + box.w - 2.5), endY - 0.3, 1.2, 2.3)
  }
}
