// The one place where pipeline facts become the office's imagery and words (spec/architecture.md,
// "Vocabulary"). Pure functions, tested in Node without a browser.
//
// Every motion takes its loudness from LOUDNESS, through motion(). Nothing else sets an amplitude
// or a rate (REQ-SIGNALS-005). Only calls reach 4, and with prefers-reduced-motion everything below
// 4 stands still while calls move gently.

/**
 * A level of loudness and how much it moves.
 * @typedef {object} Loudness
 * @property {0 | 1 | 2 | 3 | 4} level
 * @property {'still' | 'ambient' | 'work' | 'event' | 'call'} kind
 * @property {number} amplitude  How far it moves, from 0 to 1, as a share of the thing's own size.
 * @property {number} rate       Cycles a second. A motion played once lasts one cycle.
 */

/**
 * The loudness table, by level.
 * @type {readonly Readonly<Loudness>[]}
 */
export const LOUDNESS = Object.freeze([
  Object.freeze({ level: 0, kind: 'still', amplitude: 0, rate: 0 }),
  Object.freeze({ level: 1, kind: 'ambient', amplitude: 0.1, rate: 0.25 }),
  Object.freeze({ level: 2, kind: 'work', amplitude: 0.3, rate: 0.5 }),
  Object.freeze({ level: 3, kind: 'event', amplitude: 0.6, rate: 0.8 }),
  Object.freeze({ level: 4, kind: 'call', amplitude: 1, rate: 1.2 }),
])

/**
 * Every motion the office makes, with its level in the loudness table. The table's rows, from
 * spec/architecture.md; the stories that draw each thing use these names.
 */
export const MOTIONS = Object.freeze({
  'office.rest': 0,
  'office.props': 0,
  'note.rest': 0,
  'office.leave': 1,
  'note.tick': 2,
  'note.swap': 2,
  'worker.type': 2,
  'worker.walk': 2,
  'qa.walk': 2,
  'qa.write': 2,
  'lead.retro': 2,
  'lead.roll': 2,
  'office.launch': 3,
  'office.arrive': 3,
  'worker.cheer': 3,
  'qa.result': 3,
  'lead.phone': 4,
  'worker.read': 4,
  'worker.ask': 4,
})

/** @typedef {keyof typeof MOTIONS} MotionName */

/**
 * How much a motion moves: its level, amplitude and rate, after reduced motion.
 * @param {MotionName} name
 * @param {{ reduced?: boolean }} [options]  reduced: the person prefers reduced motion.
 * @returns {{ level: number, kind: Loudness['kind'], amplitude: number, rate: number }}
 */
export function motion(name, { reduced = false } = {}) {
  const row = LOUDNESS[MOTIONS[name]]
  if (!reduced) return { level: row.level, kind: row.kind, amplitude: row.amplitude, rate: row.rate }
  if (row.kind !== 'call') return { level: row.level, kind: row.kind, amplitude: 0, rate: 0 }
  return { level: row.level, kind: row.kind, amplitude: row.amplitude / 4, rate: row.rate / 2 }
}

/**
 * How long a motion played once lasts, in milliseconds: one cycle, or nothing when it stands still.
 * @param {{ rate: number }} m
 */
export function once(m) {
  return m.rate > 0 ? 1000 / m.rate : 0
}

/** The one plain line the overview shows over its empty office (REQ-DOCKS-006). */
export const EMPTY_LINE = 'No Epikloop project is active.'

/** What an office's description says when its project has no phase planned. */
export const NO_PHASES = 'No phases planned'

/**
 * Whether a phase is done: `phase-N` is tagged, or every story in it has landed and none of them is
 * in the MVP set, so no retro waits on it (spec/architecture.md, "The whiteboard").
 * @param {import('../shared/state.js').Phase} phase
 */
export function phaseDone(phase) {
  if (phase.tagged) return true
  return phase.stories.every((story) => story.landedAt !== null && !story.mvp)
}

/**
 * The phase under way, the one an office's whiteboard holds: the lowest phase with a story whose
 * worker is at work, or else the lowest phase not yet done, or else the highest phase. Null when no
 * phase is planned.
 * @param {import('../shared/state.js').Phase[]} phases
 * @param {{ story: string }[]} [workers]  The story-workers at work.
 * @returns {import('../shared/state.js').Phase | null}
 */
export function phaseUnderWay(phases, workers = []) {
  if (phases.length === 0) return null
  const sorted = [...phases].sort((a, b) => a.n - b.n)
  const working = new Set(workers.map((w) => w.story))
  return (
    sorted.find((phase) => phase.stories.some((story) => working.has(story.id))) ??
    sorted.find((phase) => !phaseDone(phase)) ??
    sorted[sorted.length - 1]
  )
}

/**
 * The colour of a sticky note, by its story's tier: teal for T1, amber for T2 and coral for T3, the
 * colours of the robots that build each. A story the plan gives no tier is coral, as T3 is.
 */
export const NOTE_COLOURS = Object.freeze({ T1: '#5fb3a5', T2: '#e9b04a', T3: '#e07f62' })

/**
 * A sticky note on the whiteboard, for one story of the phase under way.
 * @typedef {object} Note
 * @property {string} id      The story's id.
 * @property {'T1' | 'T2' | 'T3'} tier  Its tier, T3 when the plan doesn't say.
 * @property {string} colour  Its tier's colour.
 * @property {boolean} ticked Whether its story has landed.
 */

/**
 * The sticky notes of a phase, one per story, in plan order.
 * @param {import('../shared/state.js').Phase} phase
 * @returns {Note[]}
 */
export function notesOf(phase) {
  return phase.stories.map((story) => {
    const tier = story.tier ?? 'T3'
    return { id: story.id, tier, colour: NOTE_COLOURS[tier], ticked: story.landedAt !== null }
  })
}

/**
 * A story at work: one whose worker is at work and which hasn't landed, with its tier, T3 when the
 * plan doesn't say, as its sticky note's.
 * @typedef {{ story: string, tier: 'T1' | 'T2' | 'T3', since: string }} AtWork
 */

/**
 * The stories at work in a project, each once, in the order their workers began, then by id. A
 * story that has landed is no longer at work, even while its worker's turn goes on.
 * @param {import('../shared/state.js').Phase[]} phases
 * @param {{ story: string, since: string }[]} [workers]  The story-workers at work.
 * @returns {AtWork[]}
 */
export function atWork(phases, workers = []) {
  /** @type {Map<string, import('../shared/state.js').Story>} */
  const stories = new Map()
  for (const phase of phases) for (const story of phase.stories) stories.set(story.id, story)
  /** @type {Map<string, AtWork>} */
  const first = new Map()
  for (const worker of workers) {
    const story = stories.get(worker.story)
    if (story !== undefined && story.landedAt !== null) continue
    const was = first.get(worker.story)
    if (was !== undefined && was.since <= worker.since) continue
    first.set(worker.story, { story: worker.story, tier: story?.tier ?? 'T3', since: worker.since })
  }
  return [...first.values()].sort((a, b) => (a.since < b.since ? -1 : a.since > b.since ? 1 : a.story < b.story ? -1 : a.story > b.story ? 1 : 0))
}

/**
 * A phase's landed count in the office's words, as `Phase 3 · 5 of 6 landed`, with `· launched`
 * after it once the project is tagged `mvp`, when the phase holds an MVP story (REQ-SHIPS-005), or
 * else `· in retro` while its retro runs (REQ-SHIPS-004).
 * @param {import('../shared/state.js').Phase} phase
 * @param {boolean} [mvp]  The project's mvp tag exists.
 */
export function phaseCount(phase, mvp = false) {
  const landed = phase.stories.filter((story) => story.landedAt !== null).length
  const out = mvp && phase.stories.some((story) => story.mvp) ? ' · launched' : phase.inRetro ? ' · in retro' : ''
  return `Phase ${phase.n} · ${landed} of ${phase.stories.length} landed${out}`
}

/**
 * An office button's accessible description: each phase's landed count, by phase, as
 * `Phase 3 · 5 of 6 landed; Phase 4 · 0 of 2 landed`, with `· launched` after a launched phase's
 * count and `· in retro` after one whose retro runs, then each story at work, as `4.1 at work`.
 * @param {import('../shared/state.js').Phase[]} phases
 * @param {{ story: string, since: string }[]} [workers]  The story-workers at work.
 * @param {boolean} [mvp]  The project's mvp tag exists.
 */
export function officeDescription(phases, workers = [], mvp = false) {
  const counts = phases.length === 0 ? [NO_PHASES] : phases.map((phase) => phaseCount(phase, mvp))
  return [...counts, ...atWork(phases, workers).map((w) => `${w.story} at work`)].join('; ')
}

/** What a label says for a cost that wasn't reported, never $0 (REQ-LABELS-003). */
export const NO_COST = 'no cost reported'

/** What a label says for a wall time that wasn't reported, when a story has no cost row. */
export const NO_TIME = 'no time reported'

const DOLLARS = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 })

/**
 * A cost in the labels' words: list-price US dollars, to the cent, as `$4.20 list price`, or
 * `no cost reported` when there is none (REQ-LABELS-003). A cost above nothing that rounds to no
 * cent reads `under $0.01 list price`, so a reported cost never reads as $0.00.
 * @param {number | null} cost
 */
export function price(cost) {
  if (cost === null || !Number.isFinite(cost)) return NO_COST
  if (cost > 0 && cost < 0.005) return `under ${DOLLARS.format(0.01)} list price`
  return `${DOLLARS.format(cost)} list price`
}

/**
 * A wall time in the labels' words, to the minute: `14 min`, `2 h 10 min` or `2 h`, `under 1 min`
 * for less than half a minute above nothing, and `no time reported` when there is none.
 * @param {number | null} seconds
 */
export function duration(seconds) {
  if (seconds === null || !Number.isFinite(seconds)) return NO_TIME
  const minutes = Math.round(seconds / 60)
  if (minutes === 0) return seconds > 0 ? 'under 1 min' : '0 min'
  const hours = Math.floor(minutes / 60)
  const rest = minutes % 60
  if (hours === 0) return `${rest} min`
  return rest === 0 ? `${hours} h` : `${hours} h ${rest} min`
}

/**
 * The sum of the values that are there, or null when none is.
 * @param {(number | null)[]} values
 */
function total(values) {
  /** @type {number | null} */
  let sum = null
  for (const value of values) if (value !== null) sum = (sum ?? 0) + value
  return sum
}

/**
 * A sticky note's label: the story's id, its state, its wall time and its cost, as
 * `3.2 · landed · 14 min · $0.84 list price` (REQ-LABELS-002, REQ-LABELS-003).
 * @param {import('../shared/state.js').Story} story
 */
export function noteLabel(story) {
  const state = story.landedAt === null ? 'not landed' : 'landed'
  return `${story.id} · ${state} · ${duration(story.wall)} · ${price(story.cost)}`
}

/** How long a title a worker's bubble holds whole, in characters (DECISION-024). */
export const TITLE_FITS = 24

/**
 * A title as a worker's bubble holds it: whole up to 24 characters; longer, cut after the last word
 * that fits in 24 and ended in an ellipsis, as `Password reset by…`. A first word longer than 24 is
 * cut at 24.
 * @param {string} title
 */
export function cutTitle(title) {
  const whole = title.trim()
  if (whole.length <= TITLE_FITS) return whole
  const head = whole.slice(0, TITLE_FITS + 1)
  // The last space within the first 25 characters ends the last word that fits in 24.
  const end = head.lastIndexOf(' ')
  const kept = (end > 0 ? head.slice(0, end) : whole.slice(0, TITLE_FITS)).trimEnd()
  return `${kept}…`
}

/**
 * The words of a worker's bubble, in a zoomed office or each office of the split: its story's ID and
 * title, as `3.3 · session store`, the title cut past 24 characters; a story missing from the plan,
 * or one without a title, shows its ID alone (REQ-LABELS-002, DECISION-024).
 * @param {import('../shared/state.js').Phase[]} phases
 * @param {string} id
 */
export function bubbleWords(phases, id) {
  for (const phase of phases) {
    for (const story of phase.stories) {
      if (story.id !== id) continue
      const title = typeof story.title === 'string' ? cutTitle(story.title) : ''
      return title === '' ? id : `${id} · ${title}`
    }
  }
  return id
}

/**
 * A whiteboard's label: the phase under way, its landed count, `launched` once the project is tagged
 * `mvp` when the phase holds an MVP story, or else `in retro` while its retro runs, then its stories'
 * wall time and cost, each summed over the stories that report one, as
 * `Phase 3 · 5 of 6 landed · 2 h 10 min · $4.20 list price` (REQ-LABELS-002, REQ-LABELS-003,
 * REQ-SHIPS-004, REQ-SHIPS-005).
 * @param {import('../shared/state.js').Phase} phase
 * @param {boolean} [mvp]  The project's mvp tag exists.
 */
export function boardLabel(phase, mvp = false) {
  const wall = total(phase.stories.map((story) => story.wall))
  const cost = total(phase.stories.map((story) => story.cost))
  return `${phaseCount(phase, mvp)} · ${duration(wall)} · ${price(cost)}`
}

/**
 * A parked question's label: its ID, the day it was parked, and the stories it blocks, as
 * `Q-007 · parked 2026-10-28 · blocks 3.2`, `blocks 3.2, 3.4` for more than one, and
 * `blocks nothing` for none (REQ-SIGNALS-002).
 * @param {import('../shared/state.js').Question} question
 */
export function questionLabel(question) {
  const blocks = question.blocks.length === 0 ? 'nothing' : question.blocks.join(', ')
  return `${question.id} · parked ${question.date} · blocks ${blocks}`
}

/**
 * The team lead's label while it is on the phone: each parked question in its label's words, on a
 * line of its own, in the queue's order, as `Q-007 · parked 2026-10-28 · blocks 3.2`; null when no
 * question is parked, so the lead at rest shows none (REQ-SIGNALS-002).
 * @param {import('../shared/state.js').Question[]} questions
 * @returns {string | null}
 */
export function leadLabel(questions) {
  return questions.length === 0 ? null : questions.map(questionLabel).join('\n')
}

/**
 * The tier of a story, from its project's phases, or T3 when the plan doesn't say: only a T3 story
 * awaits review.
 * @param {import('../shared/state.js').Phase[]} phases
 * @param {string} id
 * @returns {'T1' | 'T2' | 'T3'}
 */
function tierOf(phases, id) {
  for (const phase of phases) for (const story of phase.stories) if (story.id === id && story.tier !== null) return story.tier
  return 'T3'
}

/**
 * A review's label: the story awaiting review and its tier, as `3.2 · T3 · awaiting review`
 * (REQ-SIGNALS-003).
 * @param {import('../shared/state.js').Review} review
 * @param {import('../shared/state.js').Phase[]} [phases]  The project's phases, for the story's tier.
 */
export function reviewLabel(review, phases = []) {
  return `${review.story} · ${tierOf(phases, review.story)} · awaiting review`
}

/** @type {Map<string, Intl.DateTimeFormat>} */
const clocks = new Map()

/**
 * A time of day on a 24-hour clock, as `14:02`, in the page's own time zone unless one is given.
 * @param {string} ts  ISO 8601.
 * @param {string} [timeZone]  An IANA time zone, such as `UTC`.
 */
export function clockTime(ts, timeZone) {
  const key = timeZone ?? ''
  let clock = clocks.get(key)
  if (clock === undefined) {
    clock = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZone })
    clocks.set(key, clock)
  }
  return clock.format(new Date(ts))
}

/**
 * A prompt's label: that a session waits on a permission prompt, since when, and the story whose
 * worker asked when the event names one, as `permission prompt · since 14:02 · 3.2`, or
 * `permission prompt · since 14:02` (REQ-SIGNALS-004).
 * @param {import('../shared/state.js').Prompt} prompt
 * @param {string} [timeZone]  An IANA time zone for the time; the page's own when not given.
 */
export function promptLabel(prompt, timeZone) {
  const story = prompt.story === null ? '' : ` · ${prompt.story}`
  return `permission prompt · since ${clockTime(prompt.since, timeZone)}${story}`
}

/**
 * A gate run's label: that the project's gates run, in which mode, and since when, as
 * `gates running · full · since 14:05` (REQ-SIGNALS-001).
 * @param {import('../shared/state.js').GateRun} run
 * @param {string} [timeZone]  An IANA time zone for the time; the page's own when not given.
 */
export function runLabel(run, timeZone) {
  return `gates running · ${run.mode} · since ${clockTime(run.since, timeZone)}`
}

/**
 * A gate run's result, as the QA lead shows it: whether its gates passed, in which mode, and when
 * its result came, with the failed gates' names after a failure, as `gates passed · full · 14:07`
 * or `gates failed · full · 14:07 · lint, test` (REQ-SIGNALS-001).
 * @param {import('../shared/state.js').GateResult} result
 * @param {string} [timeZone]  An IANA time zone for the time; the page's own when not given.
 */
export function gateResultLabel(result, timeZone) {
  const at = clockTime(result.at, timeZone)
  if (result.passed) return `gates passed · ${result.mode} · ${at}`
  return `gates failed · ${result.mode} · ${at}${result.failed.length === 0 ? '' : ` · ${result.failed.join(', ')}`}`
}

/**
 * The QA lead's label: the result it shows, if it shows one, then each run under way in the
 * run's words, in the order they started, each on a line of its own, so two runs at once are
 * both listed; none when it neither checks nor shows (REQ-SIGNALS-001).
 * @param {import('../shared/state.js').GateRun[]} runs
 * @param {import('../shared/state.js').GateResult | null} shown
 * @param {string} [timeZone]  An IANA time zone for the times; the page's own when not given.
 * @returns {string | null}
 */
export function qaLabel(runs, shown, timeZone) {
  const lines = [...(shown === null ? [] : [gateResultLabel(shown, timeZone)]), ...runs.map((run) => runLabel(run, timeZone))]
  return lines.length === 0 ? null : lines.join('\n')
}

/**
 * A worker's label: its story, its tier, and since when it has been at work, as
 * `3.2 · T1 · at work · since 14:02` (REQ-LABELS-002).
 * @param {AtWork} worker
 * @param {string} [timeZone]  An IANA time zone for the time; the page's own when not given.
 */
export function workerLabel(worker, timeZone) {
  return `${worker.story} · ${worker.tier} · at work · since ${clockTime(worker.since, timeZone)}`
}

/**
 * What the office draws at a point: an office's whiteboard, its team lead, one of its sticky notes,
 * one of its workers, or one of its workers reading at the glass office, by story, or one of its
 * workers asking at the copier, by the session it asks for, or its QA lead checking the gates, with
 * the run whose result it shows, if it shows one.
 * @typedef {{ office: string, kind: 'board' } | { office: string, kind: 'lead' } | { office: string, kind: 'note' | 'worker' | 'review', story: string } | { office: string, kind: 'prompt', session: string } | { office: string, kind: 'qa', result: string | null }} OfficeThing
 */

/**
 * The label of what the office draws at a point, from the state: the whiteboard's for its board,
 * which holds the phase under way, a note's for a sticky note, in its story's words, a
 * worker's for a story at work, a review's for a worker reading at the glass office, as
 * `3.2 · T3 · awaiting review`, a prompt's for a worker asking at the copier, in its label's words,
 * as `permission prompt · since 14:02 · 3.2`, the team lead's while a question is parked, and the
 * QA lead's while it checks the gates or shows a result, as `gates running · full · since 14:05`.
 * None for a clean board, the room, a lead at rest, or a thing the state no longer holds
 * (REQ-LABELS-002, REQ-LABELS-003, REQ-SIGNALS-001, REQ-SIGNALS-002, REQ-SIGNALS-003,
 * REQ-SIGNALS-004).
 * @param {{ id: string, mvp?: boolean, phases: import('../shared/state.js').Phase[], workers?: { story: string, since: string }[], questions?: import('../shared/state.js').Question[], reviews?: import('../shared/state.js').Review[], prompts?: import('../shared/state.js').Prompt[], gateRuns?: import('../shared/state.js').GateRun[], gateResults?: import('../shared/state.js').GateResult[] }[]} projects
 * @param {OfficeThing | null} thing
 * @param {string} [timeZone]  An IANA time zone for a worker's or a prompt's time; the page's own
 *   when not given.
 * @returns {string | null}
 */
export function officeLabelOf(projects, thing, timeZone) {
  if (thing === null) return null
  const project = projects.find((p) => p.id === thing.office)
  if (project === undefined) return null
  const workers = project.workers ?? []
  if (thing.kind === 'lead') return leadLabel(project.questions ?? [])
  if (thing.kind === 'qa') {
    const shown = thing.result === null ? null : ((project.gateResults ?? []).find((r) => r.run === thing.result) ?? null)
    return qaLabel(project.gateRuns ?? [], shown, timeZone)
  }
  if (thing.kind === 'prompt') {
    const prompt = (project.prompts ?? []).find((p) => p.session === thing.session)
    return prompt === undefined ? null : promptLabel(prompt, timeZone)
  }
  if (thing.kind === 'review') {
    const review = (project.reviews ?? []).find((r) => r.story === thing.story)
    return review === undefined ? null : reviewLabel(review, project.phases)
  }
  if (thing.kind === 'worker') {
    const worker = atWork(project.phases, workers).find((w) => w.story === thing.story)
    return worker === undefined ? null : workerLabel(worker, timeZone)
  }
  const phase = phaseUnderWay(project.phases, workers)
  if (phase === null) return null
  if (thing.kind === 'board') return boardLabel(phase, project.mvp === true)
  const story = phase.stories.find((s) => s.id === thing.story)
  return story === undefined ? null : noteLabel(story)
}

/**
 * @param {number} n
 * @param {string} one
 */
const count = (n, one) => (n === 1 ? `1 ${one}` : `${n} ${one}s`)

/**
 * Words joined as a list: `a`, `a and b`, `a, b and c`.
 * @param {string[]} words
 */
const listed = (words) => (words.length < 2 ? words.join('') : `${words.slice(0, -1).join(', ')} and ${words[words.length - 1]}`)

/**
 * What the status region says, one line a project that waits on the human, in the projects' order,
 * as `atlas waits on 1 question: Q-002 · parked 2026-11-04 · blocks 2.3`, each question in its
 * label's words, or `atlas waits on 1 question and 1 review: Q-002 · parked 2026-11-04 · blocks 2.3;
 * 2.2 · T3 · awaiting review`, each review in its label's words, after the questions, and then
 * each prompt in its label's words: `atlas waits on 1 question, 1 review and 1 prompt: …;
 * permission prompt · since 14:02 · 3.2`. A review question is a review, never a question too, so it
 * counts once. A project that waits on nothing has no line, so the region is empty when nothing
 * waits.
 * @param {{ name: string, questions: import('../shared/state.js').Question[], reviews?: import('../shared/state.js').Review[], prompts?: import('../shared/state.js').Prompt[], phases?: import('../shared/state.js').Phase[] }[]} projects
 * @param {string} [timeZone]  An IANA time zone for the prompts' times; the page's own when not given.
 * @returns {string[]}
 */
export function statusLines(projects, timeZone) {
  return projects.flatMap(({ name, questions, reviews = [], prompts = [], phases = [] }) => {
    const counts = [
      ...(questions.length === 0 ? [] : [count(questions.length, 'question')]),
      ...(reviews.length === 0 ? [] : [count(reviews.length, 'review')]),
      ...(prompts.length === 0 ? [] : [count(prompts.length, 'prompt')]),
    ]
    if (counts.length === 0) return []
    const words = [
      ...questions.map(questionLabel),
      ...reviews.map((review) => reviewLabel(review, phases)),
      ...prompts.map((prompt) => promptLabel(prompt, timeZone)),
    ]
    return [`${name} waits on ${listed(counts)}: ${words.join('; ')}`]
  })
}

/** What the list view says of an office that waits on nothing. */
export const NOTHING_WAITS = 'Nothing waits.'

/**
 * An office in the list view, the same state the office draws, in the labels' words.
 * @typedef {object} ListedOffice
 * @property {string} id
 * @property {string} name
 * @property {{ label: string, stories: string[] }[]} phases  Each phase in its whiteboard's words,
 *   by phase, with each of its stories in its sticky note's words, in plan order.
 * @property {string[]} waits  What waits on the human: each question in its label's words, then each
 *   review in its own, then each prompt in its own. Empty when nothing does.
 * @property {string[]} running  Each gate run under way, in its label's words.
 */

/**
 * The list view's offices, for when the office can't be drawn: each office with its phases, its
 * stories and what waits, in the labels' words, in the projects' order (REQ-DOCKS-007).
 * @param {{ id: string, name: string, mvp: boolean, phases: import('../shared/state.js').Phase[], questions: import('../shared/state.js').Question[], reviews?: import('../shared/state.js').Review[], prompts?: import('../shared/state.js').Prompt[], gateRuns?: import('../shared/state.js').GateRun[] }[]} projects
 * @param {string} [timeZone]  An IANA time zone for the prompts' and runs' times; the page's own
 *   when not given.
 * @returns {ListedOffice[]}
 */
export function officeList(projects, timeZone) {
  return projects.map(({ id, name, mvp, phases, questions, reviews = [], prompts = [], gateRuns = [] }) => ({
    id,
    name,
    phases: phases.map((phase) => ({ label: boardLabel(phase, mvp), stories: phase.stories.map(noteLabel) })),
    waits: [
      ...questions.map(questionLabel),
      ...reviews.map((review) => reviewLabel(review, phases)),
      ...prompts.map((prompt) => promptLabel(prompt, timeZone)),
    ],
    running: gateRuns.map((run) => runLabel(run, timeZone)),
  }))
}
