// The one file that opens an EventSource, and only to /events (DECISION-010). It hands the page
// each state the server sends (REQ-SOURCES-004). The browser reconnects by itself, and the server
// answers a reconnect with the whole state again.

/**
 * Listens to Harbor's event stream.
 * @param {(state: import('../shared/state.js').HarborState) => void} onState  Called with each
 *   state, in order. A message of any other format is ignored.
 * @returns {() => void} Closes the stream.
 */
export function connect(onState) {
  const source = new EventSource('/events')
  source.addEventListener('state', (event) => {
    /** @type {import('../shared/state.js').HarborState} */
    let state
    try {
      state = JSON.parse(/** @type {MessageEvent<string>} */ (event).data)
    } catch {
      return
    }
    if (state === null || typeof state !== 'object' || state.format !== 1 || !Array.isArray(state.projects)) return
    onState(state)
  })
  return () => source.close()
}
