// The QA lead checking the gates, as rules the stage follows (REQ-SIGNALS-001). Pure, so it is
// tested in Node.
//
// While a gate run is under way, the QA lead walks to the desk of the worker at work in the run's
// session, or stays at its own spot when there is none, and writes on its clipboard. This is work,
// not a call: it walks and writes at loudness 2, stands still under reduced motion, and no status
// line or tab count says it. When the run's result arrives, it gives a thumbs up if every gate
// passed, or holds up a red cross if one failed, once, as an event, and then walks back. With two
// runs at once it checks the newer one.
import { motion } from '../vocabulary.js'
import { AISLE } from './calls.js'
import { DESKS, SPOTS } from './layout.js'

/** Where the QA lead stands to check at a desk: right of the front of its chair, in plate pixels. */
export const BESIDE = Object.freeze({ x: 52, y: 6 })

/** How far the QA lead's pen hand lifts as it writes, at amplitude 1, in its own pixels. */
export const WRITE = 4

/** How high the QA lead lifts as it shows a result, at amplitude 1, in its own pixels. */
export const SHOW = 8

/** @typedef {{ x: number, y: number }} Point */

/**
 * The run the QA lead checks: the newest of the runs under way, by when it started, or null when
 * none is.
 * @param {import('../../shared/state.js').GateRun[]} runs
 * @returns {import('../../shared/state.js').GateRun | null}
 */
export function checked(runs) {
  /** @type {import('../../shared/state.js').GateRun | null} */
  let newest = null
  for (const run of runs) {
    if (newest === null) {
      newest = run
      continue
    }
    const a = Date.parse(run.since)
    const b = Date.parse(newest.since)
    if (a > b || (a === b && run.run > newest.run)) newest = run
  }
  return newest
}

/**
 * Where the QA lead checks a run: beside the desk of the worker at work in the run's session, or at
 * its own spot when there is none, or when no run is under way.
 * @param {import('../../shared/state.js').GateRun | null} run
 * @param {{ story: string | null }[]} desks  Who has each desk, from the left.
 * @param {{ story: string, session?: string }[]} working  The stories at work, each with its
 *   worker's session when known.
 * @returns {Point}
 */
export function checkAt(run, desks, working) {
  if (run === null) return SPOTS.qa
  const worker = working.find((w) => w.session !== undefined && w.session === run.session)
  const desk = worker === undefined ? -1 : desks.findIndex((d) => d.story === worker.story)
  const at = DESKS[desk]
  if (at === undefined) return SPOTS.qa
  return { x: at.front.x + BESIDE.x, y: at.front.y + BESIDE.y }
}

/**
 * The result the QA lead shows: that of the run it checked, once that run is no longer under way and
 * its result lines have come. None while it still runs, or when it ended without a result, as after
 * 30 minutes.
 * @param {string | null} run  The run it checked, by detail.run.
 * @param {import('../../shared/state.js').GateRun[]} runs  The runs under way.
 * @param {import('../../shared/state.js').GateResult[]} results
 * @returns {import('../../shared/state.js').GateResult | null}
 */
export function resultOf(run, runs, results) {
  if (run === null || runs.some((r) => r.run === run)) return null
  return results.find((r) => r.run === run) ?? null
}

/**
 * The QA lead's pose as it shows a result: a thumbs up for a pass, a red cross for a failure.
 * @param {import('../../shared/state.js').GateResult} result
 */
export function showPose(result) {
  return result.passed ? 'qa-thumbs' : 'qa-cross'
}

/**
 * The QA lead's walk from a point on the floor to another: down to the aisle under the desks, along
 * it, and up to where it stands, so it passes in front of the chairs.
 * @param {Point} from
 * @param {Point} to
 * @returns {Point[]}
 */
export function toCheck(from, to) {
  /** @type {Point[]} */
  const route = [from]
  if (from.x !== to.x) route.push({ x: from.x, y: Math.max(AISLE, from.y) }, { x: to.x, y: Math.max(AISLE, to.y) })
  route.push(to)
  return route.filter((p, i) => i === 0 || p.x !== route[i - 1].x || p.y !== route[i - 1].y)
}

/**
 * How far the QA lead's pen hand lifts at a moment as it writes, in its own pixels: work, so it
 * stands still under reduced motion.
 * @param {number} ms  How long it has written, in milliseconds.
 * @param {boolean} [reduced]
 */
export function writeBob(ms, reduced = false) {
  const m = motion('qa.write', { reduced })
  if (m.rate === 0) return 0
  return (0.5 - 0.5 * Math.cos((2 * Math.PI * m.rate * ms) / 1000)) * WRITE * m.amplitude
}

/**
 * How high the QA lead lifts at a share of the way through showing a result, in its own pixels: an
 * event, played once, held as long without the lift under reduced motion.
 * @param {number} t  From 0 to 1.
 * @param {boolean} [reduced]
 */
export function showLift(t, reduced = false) {
  return Math.sin(Math.min(1, Math.max(0, t)) * Math.PI) * SHOW * motion('qa.result', { reduced }).amplitude
}
