// The workers at their desks, as rules the stage follows (REQ-SHIPS-006, REQ-SHIPS-007). Pure, so it
// is tested in Node.
//
// Each story at work has a worker, a robot of its story's tier, which takes the first free desk
// from the left and keeps it while it works. A fifth worker at once waits, undrawn, until a desk is
// free. An empty desk keeps the chair of the last robot that sat there. A worker types frames a, b,
// a and c, with a pause to think in each cycle, and its screen shows code seeded by its story's ID.
import { motion, once } from '../vocabulary.js'
import { DESKS } from './layout.js'

/** @typedef {import('./layout.js').Seat} Seat */

/**
 * A worker's robot, by its story's tier: teal for T1, amber for T2 and coral for T3.
 * @param {'T1' | 'T2' | 'T3'} tier
 * @returns {Seat}
 */
export function seatOf(tier) {
  return tier === 'T1' ? 't1' : tier === 'T2' ? 't2' : 't3'
}

/**
 * A desk, as the rules see it: the story whose worker has it, if any, and whose chair waits there.
 * @typedef {{ story: string | null, chair: Seat }} Desk
 */

/** The desks at first: none taken, the chairs teal, amber, coral and teal from the left. @returns {Desk[]} */
export function firstDesks() {
  return DESKS.map((d) => ({ story: null, chair: d.chair }))
}

/**
 * A worker taking a desk, or a robot cheering at one: which story, at which desk, its robot, and
 * whose chair the desk had before.
 * @typedef {{ story: string, desk: number, seat: Seat, was: Seat }} Taken
 */

/**
 * The desks after a change in the stories at work. A desk whose story is no longer at work is free,
 * and keeps its chair. Then each story that landed with no worker seen takes the first free desk to
 * cheer at, and each story at work without a desk takes the first free desk from the left, in the
 * order its worker began; once none is free, the rest wait. A desk that is blocked, where a robot
 * still cheers, isn't free. The robot that takes a desk leaves its own chair there.
 * @param {Desk[]} desks
 * @param {{ story: string, tier: 'T1' | 'T2' | 'T3' }[]} working  The stories at work, in order.
 * @param {{ blocked?: Set<number>, cheers?: { story: string, tier: 'T1' | 'T2' | 'T3' }[] }} [options]
 *   blocked: desks not free; cheers: stories that landed with no worker seen.
 * @returns {{ desks: Desk[], sat: Taken[], left: { story: string, desk: number }[], cheered: Taken[] }}
 *   sat: the workers that take a desk; left: the workers whose desk is free again; cheered: where
 *   each landing with no worker seen cheers. A landing finds no desk when none is free.
 */
export function seat(desks, working, { blocked = new Set(), cheers = [] } = {}) {
  const at = new Set(working.map((w) => w.story))
  const next = desks.map((d) => ({ ...d }))
  /** @type {{ story: string, desk: number }[]} */
  const left = []
  next.forEach((desk, i) => {
    if (desk.story !== null && !at.has(desk.story)) {
      left.push({ story: desk.story, desk: i })
      desk.story = null
    }
  })
  const held = new Set(blocked)
  const free = () => next.findIndex((d, i) => d.story === null && !held.has(i))
  /** @type {Taken[]} */
  const cheered = []
  for (const landing of cheers) {
    const i = free()
    if (i < 0) break
    const robot = seatOf(landing.tier)
    cheered.push({ story: landing.story, desk: i, seat: robot, was: next[i].chair })
    next[i].chair = robot
    held.add(i)
  }
  const seated = new Set(next.map((d) => d.story))
  /** @type {Taken[]} */
  const sat = []
  for (const worker of working) {
    if (seated.has(worker.story)) continue
    const i = free()
    if (i < 0) break
    const robot = seatOf(worker.tier)
    sat.push({ story: worker.story, desk: i, seat: robot, was: next[i].chair })
    next[i] = { story: worker.story, chair: robot }
    seated.add(worker.story)
  }
  return { desks: next, sat, left, cheered }
}

/** The typing frames, in the order they play. */
export const TYPING = Object.freeze(/** @type {const} */ (['type-a', 'type-b', 'type-a', 'type-c']))

/** Of each typing cycle, the share at the end spent thinking, both hands down. */
export const PAUSE = 1 / 6

/** How many frames each typing cycle steps through. */
export const STEPS = 12

/**
 * The typing frame at a moment: frames a, b, a and c in turn, each a twelfth of a cycle of work's
 * rate, and frame a through the pause at the end of each cycle. Under reduced motion, frame a.
 * @param {number} ms  How long it has typed, in milliseconds, plus its desk's own offset.
 * @param {boolean} [reduced]
 * @returns {typeof TYPING[number]}
 */
export function typingFrame(ms, reduced = false) {
  const cycle = once(motion('worker.type', { reduced }))
  if (cycle === 0) return 'type-a'
  const local = ((ms % cycle) + cycle) % cycle
  if (local >= cycle * (1 - PAUSE)) return 'type-a'
  return TYPING[Math.floor(local / (cycle / STEPS)) % TYPING.length]
}

/**
 * A seed from a story's ID, the same on every machine.
 * @param {string} id
 */
export function seedOf(id) {
  let h = 2166136261
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i)
    h = Math.imul(h, 16777619) >>> 0
  }
  return h
}

/** The inks of code on a screen. */
export const CODE_INKS = Object.freeze(['#2bb3a0', '#f0a83a', '#e0475f', '#e9e1cf', '#8fb4ff', '#c3a3e6'])

/**
 * A line of code on a screen: its indent and its tokens, by length in characters, and its length.
 * @typedef {{ indent: number, tokens: { len: number, ink: string }[], chars: number }} CodeLine
 */

/**
 * The code a screen shows, from a seed: 240 lines, some blank, the rest indented up to three deep
 * with one to four tokens each, as the prototype draws it.
 * @param {number} seed
 * @returns {CodeLine[]}
 */
export function codeFor(seed) {
  let s = seed >>> 0
  const r = () => (s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 4294967296
  /** @type {CodeLine[]} */
  const lines = []
  let depth = 0
  for (let i = 0; i < 240; i++) {
    if (r() < 0.12) {
      lines.push({ indent: 0, tokens: [], chars: 0 })
      continue
    }
    depth = Math.max(0, Math.min(3, depth + (r() < 0.3 ? 1 : r() < 0.35 ? -1 : 0)))
    const tokens = []
    const n = 1 + Math.floor(r() * 4)
    for (let j = 0; j < n; j++) tokens.push({ len: 3 + Math.floor(r() * 9), ink: CODE_INKS[Math.floor(r() * CODE_INKS.length)] })
    const indent = depth * 3
    lines.push({ indent, tokens, chars: indent + tokens.reduce((a, k) => a + k.len + 1, 0) })
  }
  return lines
}
