// The retro in the lounge, as rules the stage follows (REQ-SHIPS-004). Pure, so it is tested in Node.
//
// While a phase is in its retro, the crew gathers in the lounge at the front right of the room: a
// teal, an amber and a coral robot walk in from the front, and the team lead rolls down from its spot
// by the glass office to stand beside them, pointing and talking. This is work, at loudness 2, so it
// stands still under reduced motion. A worker at work stays at its desk: the crew in the lounge are
// robots of their own. The lead takes its headset with it, so a parked question puts it on the
// phone in the lounge. Once `phase-N` is tagged, the crew goes back: the robots walk off toward the
// front and the lead rolls back to its spot.
import { motion } from '../vocabulary.js'
import { DOOR, SPOTS } from './layout.js'

/**
 * Where the crew stands in the lounge, in plate pixels: the teal, amber and coral robots on the rug
 * in front of the sofa, from the left, and the team lead right of them, facing them.
 * @type {readonly Readonly<{ seat: import('./layout.js').Seat, at: Readonly<{ x: number, y: number }> }>[]}
 */
export const GATHERED = Object.freeze([
  Object.freeze({ seat: /** @type {import('./layout.js').Seat} */ ('t1'), at: Object.freeze({ x: 760, y: 556 }) }),
  Object.freeze({ seat: /** @type {import('./layout.js').Seat} */ ('t2'), at: Object.freeze({ x: 846, y: 598 }) }),
  Object.freeze({ seat: /** @type {import('./layout.js').Seat} */ ('t3'), at: Object.freeze({ x: 944, y: 574 }) }),
])

/** Where the team lead stands in the lounge, in plate pixels, right of the crew. */
export const HOST = Object.freeze({ x: 1012, y: 546 })

/**
 * Whether a project's crew gathers in the lounge: while any of its phases is in its retro.
 * @param {import('../../shared/state.js').Phase[]} phases
 */
export function inRetro(phases) {
  return phases.some((phase) => phase.inRetro === true)
}

/**
 * Where the team lead stands when it isn't on its way: in the lounge while the crew is gathered
 * there or gathering, or else at its spot by the glass office.
 * @param {boolean} gathered
 */
export function leadAt(gathered) {
  return gathered ? HOST : SPOTS.lead
}

/**
 * The team lead's pose at the retro, at a moment: pointing for the first half of each cycle of
 * work, then talking for the second, and pointing, still, under reduced motion. On the phone it
 * talks on its headset, as it does at its spot.
 * @param {number} ms  How long the retro has run, in milliseconds.
 * @param {boolean} [reduced]
 * @returns {'lead-point' | 'lead-talk'}
 */
export function hostPose(ms, reduced = false) {
  const m = motion('lead.retro', { reduced })
  if (m.rate === 0) return 'lead-point'
  const cycle = 1000 / m.rate
  return ((ms % cycle) + cycle) % cycle < cycle / 2 ? 'lead-point' : 'lead-talk'
}

/**
 * The walk of a robot of the crew into the lounge, in plate pixels: up from the front of the room to
 * its place. Walking back, it goes the other way.
 * @param {{ x: number, y: number }} at  Its place in the lounge.
 */
export function walkIn(at) {
  return [{ x: at.x, y: DOOR }, { x: at.x, y: at.y }]
}

/**
 * The team lead's roll into the lounge, in plate pixels: down from its spot by the glass office to
 * its place right of the crew. Rolling back, it goes the other way.
 */
export function rollIn() {
  return [{ x: SPOTS.lead.x, y: SPOTS.lead.y }, { x: HOST.x, y: HOST.y }]
}
