// The office, the page's one picture. The page keeps the latest state from the feed
// (REQ-SOURCES-004) and draws the overview: an office for each active project, all in view at once,
// or one dimmed empty office and the one plain line when none is (REQ-DOCKS-001, REQ-DOCKS-003,
// REQ-DOCKS-006). The overlay places a button named for each project over its office, in a
// navigation named Offices (REQ-LABELS-001). Clicking an office zooms in on it, Shift-clicking two
// opens the split, and the Overview button or Escape returns; the hash keeps the view,
// `#/office/<id>` for one office, and a kept `#/dock/<id>` opens the same (REQ-DOCKS-004,
// REQ-DOCKS-005, spec/architecture.md, "Views"). The status region and the tab say what waits
// (REQ-SIGNALS-005, REQ-SIGNALS-006). Each button's description gives each phase's landed count and
// names each story at work, each office's whiteboard holds the phase under way, and its workers sit
// at its desks (REQ-SHIPS-001 to REQ-SHIPS-003, REQ-SHIPS-006, REQ-SHIPS-007). Hovering the
// whiteboard, a sticky note or a worker shows its label by the pointer, in the element with
// role="tooltip" (REQ-LABELS-002, REQ-LABELS-003). In a zoomed office, and in each office of the
// split, each worker carries a bubble with its story's ID and title; in the overview none does
// (REQ-LABELS-002, DECISION-024). While a question is parked, the team lead is on the phone under a
// ringed bubble, in every view, and hovering it shows each question's label on a line of its own
// (REQ-SIGNALS-002, REQ-SIGNALS-005). Each T3 story awaiting review is its worker reading at the
// glass office under a ringed bubble, and hovering it shows `3.2 · T3 · awaiting review`
// (REQ-SIGNALS-003). Each session waiting on a permission prompt is a worker asking at the copier
// under a ringed bubble, and hovering it shows `permission prompt · since 14:02 · 3.2`
// (REQ-SIGNALS-004). While a gate run is under way the QA lead checks it, and hovering it shows
// `gates running · full · since 14:05`, then the result it shows, as `gates failed · full · 14:07 ·
// lint, test`; no status line or tab count says it (REQ-SIGNALS-001). While a phase is in its retro,
// the crew gathers in the lounge, and the description and the whiteboard's label say `in retro`
// (REQ-SHIPS-004). Once the project is tagged `mvp`, the office holds launch day, and the description
// and the whiteboard's label say `launched` for each phase that holds an MVP story (REQ-SHIPS-005).
// When the office can't draw, because the canvas gives no 2D context or any of its art fails to
// load, the canvas goes and the overlay shows the same state as a list: each office with its
// phases, its stories and what waits (REQ-DOCKS-007).
import { connect } from '../feed.js'
import { overlay } from '../overlay.js'
import { tab, waiting } from '../tab.js'
import { OVERVIEW, choose, format, parse, same, settle, shown } from '../views.js'
import { officeDescription, officeLabelOf, officeList, statusLines } from '../vocabulary.js'
import { speech } from './bubbles.js'
import { tiles } from './layout.js'
import { stage } from './stage.js'

/** Draws the office on the page. */
export function office() {
  const canvas = document.createElement('canvas')
  canvas.className = 'scene'
  canvas.setAttribute('aria-hidden', 'true')
  const layer = document.createElement('main')
  layer.className = 'overlay'
  document.body.append(canvas, layer)

  const tabbed = tab(document)
  const reducedQuery = window.matchMedia('(prefers-reduced-motion: reduce)')

  /** The view on the page. @type {import('../views.js').View} */
  let view = OVERVIEW
  /** The office picked for a split, if one is. @type {string | null} */
  let picked = null
  /** The ids of the offices there are, or null before the first state. @type {Set<string> | null} */
  let present = null

  /**
   * Opens a view, writing its hash. A view that falls back replaces the hash, so Back doesn't return
   * to an office that has gone.
   * @param {import('../views.js').View} next
   * @param {{ replace?: boolean }} [options]
   */
  const go = (next, { replace = false } = {}) => {
    const hash = format(next)
    if (location.hash !== hash && !(hash === '#/' && location.hash === '')) {
      if (replace) history.replaceState(null, '', hash)
      else {
        // The hashchange that follows applies it.
        location.hash = hash
        return
      }
    }
    apply(next)
  }

  /**
   * Shows a view, once the offices it names are known to be there.
   * @param {import('../views.js').View} next
   */
  const apply = (next) => {
    const settled = present === null ? next : settle(next, present)
    if (!same(settled, next)) {
      go(settled, { replace: true })
      return
    }
    view = next
    if (picked !== null && present !== null && !present.has(picked)) picked = null
    const ids = shown(view)
    dom.show(ids, picked)
    if (scene !== null) scene.show(ids)
    // What is under the pointer changes with the view.
    hover()
  }

  /**
   * A click on an office, from its button or from the canvas.
   * @param {string} id
   * @param {boolean} shift
   */
  const open = (id, shift) => {
    const next = choose({ view, picked }, id, shift)
    picked = next.picked
    if (same(next.view, view)) dom.show(shown(view), picked)
    else go(next.view)
  }

  const toOverview = () => {
    picked = null
    go(OVERVIEW)
  }

  const dom = overlay(layer, { open, overview: toOverview }, { places: 'Offices' })
  /** The projects of the latest state. @type {import('../../shared/state.js').HarborState['projects'] | null} */
  let latest = null

  /** Lists the latest state, in the grid's order, once the office can't draw. */
  const listed = () => {
    dom.list(latest === null ? [] : officeList(tiles(latest, 1, 1).flatMap(({ id }) => latest?.filter((p) => p.id === id) ?? [])))
  }

  /**
   * The office can't draw: the canvas goes, the buttons stay in the page's flow, and the list view
   * shows the state (REQ-DOCKS-007).
   */
  const broken = () => {
    scene = null
    canvas.remove()
    pointer = null
    dom.tip(null)
    dom.bubbles([])
    dom.place(null)
    listed()
    apply(view)
  }

  /**
   * After each frame: each button to its office, each worker's bubble to its point, and the label
   * of what is now under the pointer, which changes as the QA lead finishes showing a result.
   */
  const frame = () => {
    if (scene === null) return
    dom.place(scene.anchor)
    dom.bubbles(speech(scene.bubbles(), latest ?? [], shown(view)))
    hover()
  }

  /** @type {import('./stage.js').OfficeStage | null} */
  let scene = null
  try {
    scene = stage(canvas, { reduced: () => reducedQuery.matches, onFrame: () => frame(), onBroken: () => broken() })
  } catch {
    // No 2D context: the office can't draw at all.
    scene = null
  }

  canvas.addEventListener('click', (event) => {
    if (scene === null) return
    const id = scene.pick(event.offsetX, event.offsetY)
    if (id !== null) open(id, event.shiftKey)
  })

  /** Where the pointer is over the canvas, in CSS pixels from its top left, or null when it isn't. @type {{ x: number, y: number } | null} */
  let pointer = null

  /** Shows the label of what is under the pointer, or hides it (REQ-LABELS-002). */
  const hover = () => {
    if (scene === null || pointer === null || latest === null) {
      dom.tip(null)
      return
    }
    dom.tip(officeLabelOf(latest, scene.at(pointer.x, pointer.y)), pointer.x, pointer.y)
  }

  canvas.addEventListener('pointermove', (event) => {
    // The canvas covers the page from its top left, so this is the point on it and on the overlay.
    const box = canvas.getBoundingClientRect()
    pointer = { x: event.clientX - box.left, y: event.clientY - box.top }
    hover()
  })
  canvas.addEventListener('pointerleave', () => {
    pointer = null
    hover()
  })

  /** Whether a state has come yet. */
  let initial = true
  connect((state) => {
    const projects = state.projects
    latest = projects
    present = new Set(projects.map((p) => p.id))
    const described = new Map(projects.map((p) => [p.id, officeDescription(p.phases, p.workers, p.mvp)]))
    // In name order, which is the grid's and the keyboard's.
    dom.update(tiles(projects, 1, 1).map(({ id, name }) => ({ id, name, description: described.get(id) ?? '' })))
    dom.status(statusLines(projects))
    tabbed.show(waiting(projects))
    if (scene !== null) scene.update(projects, { initial })
    else listed()
    initial = false
    // An office in view that has left falls back to whatever remains.
    apply(view)
    dom.place(scene === null ? null : scene.anchor)
  })

  window.addEventListener('hashchange', () => apply(parse(location.hash)))
  window.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape' || event.defaultPrevented) return
    if (view.kind === 'overview' && picked === null) return
    toOverview()
  })
  window.addEventListener('resize', () => scene?.resize())

  if (scene === null) broken()
  apply(parse(location.hash))
}
