// Where each office sits and what stands in it, in the plate's own pixels (docs/art/README.md). Pure,
// so it is tested in Node.
//
// The overview tiles every office on a grid ordered by name, all in view at once (REQ-DOCKS-003):
// as many columns as make the offices largest in the page, each at the plate's shape. An office is
// the plate, with a chair at each of its four desks, centred under its keyboard and placed by the
// middle of its wheel base, so it stays put when a robot sits in it or gets up.

/** The plate's size, in its own pixels. */
export const PLATE = Object.freeze({ width: 1088, height: 608 })

/** Room around the offices, and between them, in CSS pixels. */
export const MARGIN = 16
export const GAP = 12

/**
 * A sprite's entry in sprites.json: [width, height, top, foot, body_x, foot_x, k], k 1 when left out.
 * @typedef {number[]} SpriteEntry
 */

/**
 * The cast: each robot's height when standing at the cubicles, in the plate's pixels, and its
 * standing sprite's height (docs/art/clay/clay-office-src.html). t1, t2 and t3 are the workers, by
 * tier; lead is the team lead and qa the QA lead.
 */
export const CAST = Object.freeze({
  t1: Object.freeze({ height: 125, stand: 244 }),
  t2: Object.freeze({ height: 150, stand: 234 }),
  t3: Object.freeze({ height: 142, stand: 251 }),
  lead: Object.freeze({ height: 145, stand: 291 }),
  qa: Object.freeze({ height: 132, stand: 296 }),
})

/** @typedef {keyof typeof CAST} Robot */
/** A worker, by its tier's robot. @typedef {'t1' | 't2' | 't3'} Seat */

/**
 * The four desks, from the left, as measured in the prototype: each chair's place, centred under its
 * keyboard; where its robot stands when it gets up, in front of the chair; its screen; and whose
 * chair waits there at first, teal, amber, coral and teal.
 * @type {readonly Readonly<{ seat: Readonly<{ x: number, y: number }>, front: Readonly<{ x: number, y: number }>, screen: Readonly<{ x: number, y: number, w: number, h: number }>, chair: Seat }>[]}
 */
export const DESKS = Object.freeze([
  Object.freeze({ seat: Object.freeze({ x: 336, y: 410 }), front: Object.freeze({ x: 336, y: 440 }), screen: Object.freeze({ x: 320, y: 247, w: 56, h: 30 }), chair: /** @type {Seat} */ ('t1') }),
  Object.freeze({ seat: Object.freeze({ x: 477, y: 410 }), front: Object.freeze({ x: 477, y: 440 }), screen: Object.freeze({ x: 452, y: 247, w: 56, h: 30 }), chair: /** @type {Seat} */ ('t2') }),
  Object.freeze({ seat: Object.freeze({ x: 617, y: 410 }), front: Object.freeze({ x: 617, y: 440 }), screen: Object.freeze({ x: 590, y: 247, w: 56, h: 30 }), chair: /** @type {Seat} */ ('t3') }),
  Object.freeze({ seat: Object.freeze({ x: 760, y: 410 }), front: Object.freeze({ x: 760, y: 440 }), screen: Object.freeze({ x: 727, y: 246, w: 57, h: 31 }), chair: /** @type {Seat} */ ('t1') }),
])

/** Where the leads stand at rest: the team lead by the glass office, the QA lead by the fourth cubicle. */
export const SPOTS = Object.freeze({ lead: Object.freeze({ x: 1012, y: 410 }), qa: Object.freeze({ x: 790, y: 440 }) })

/**
 * Where the workers reading at the glass office stand, side by side in front of it, from the left,
 * clear of the team lead, in plate pixels (REQ-SIGNALS-003).
 */
export const GLASS = Object.freeze([Object.freeze({ x: 870, y: 400 }), Object.freeze({ x: 938, y: 400 })])

/** Where a worker comes in from the front of the room and walks off to, on its way to or from the glass office. */
export const ENTRY = Object.freeze({ x: 620, y: 640 })

/** The desk phone's light in the glass office, as measured in the prototype, in plate pixels. */
export const PHONE = Object.freeze({ x: 950, y: 228 })

/**
 * Where the workers asking at the copier stand, side by side in front of it, from the left: the
 * first where the prototype has it, the second beside it, in plate pixels (REQ-SIGNALS-004).
 */
export const COPIER = Object.freeze([Object.freeze({ x: 170, y: 505 }), Object.freeze({ x: 252, y: 505 })])

/** The copier's red light, as measured in the prototype, in plate pixels. */
export const COPIER_LIGHT = Object.freeze({ x: 66, y: 439 })

/** How far below the plate's bottom edge a worker comes in from and walks off to, in plate pixels. */
export const DOOR = 640

/**
 * How much bigger things grow toward the viewer, at the height of their feet in the plate.
 * @param {number} y
 */
export function perspective(y) {
  return 1 + 0.0022 * (y - 395)
}

/**
 * A sprite placed by an anchor on the floor at a point on the plate, at its robot's size there.
 * @param {Record<string, SpriteEntry>} sprites  The sprite table.
 * @param {Robot} who
 * @param {string} name  The sprite's name.
 * @param {{ x: number, y: number }} at  Where its anchor stands.
 * @param {'body' | 'foot'} anchor  body_x for standing and walking; foot_x, the middle of the wheel
 *   base, for seated frames and chairs.
 * @returns {{ sprite: string, x: number, y: number, scale: number, k: number, left: number, top: number, width: number, height: number, ax: number, foot: number, head: number }}
 *   Its scale, its size factor, the box it is drawn in, its anchor and foot in its own pixels, and
 *   the height of its top on the plate.
 */
export function placed(sprites, who, name, at, anchor) {
  const entry = sprites[name]
  if (entry === undefined) throw new Error(`sprites.json has no ${name}`)
  const [width, height, top, foot, bodyX, footX, k = 1] = entry
  const scale = (CAST[who].height / CAST[who].stand) * perspective(at.y) * k
  const ax = anchor === 'body' ? bodyX : footX
  return {
    sprite: name,
    x: at.x,
    y: at.y,
    scale,
    k,
    left: at.x - ax * scale,
    top: at.y - foot * scale,
    width: width * scale,
    height: height * scale,
    ax,
    foot,
    head: at.y - (foot - top) * scale,
  }
}

/**
 * A desk's chair, a sprite placed by its wheel base under the desk's keyboard.
 * @param {Record<string, SpriteEntry>} sprites  The sprite table.
 * @param {number} desk  From the left, 0 to 3.
 * @param {Seat} chair  Whose chair it is.
 * @returns {{ sprite: string, x: number, y: number, scale: number, shadow: number, left: number, top: number, width: number, height: number }}
 *   Its sprite, its foot's place, its scale, the reach of the shadow under it, and the box it is
 *   drawn in, in plate pixels.
 */
export function chairAt(sprites, desk, chair) {
  const p = placed(sprites, chair, `${chair}-chair`, DESKS[desk].seat, 'foot')
  // The shadow follows the chair's size in the room, not the size factor of its sheet.
  return { sprite: p.sprite, x: p.x, y: p.y, scale: p.scale, shadow: (50 * p.scale) / p.k, left: p.left, top: p.top, width: p.width, height: p.height }
}

/**
 * The chairs an office draws at first, each a sprite placed by its foot at a point on the plate.
 * @param {Record<string, SpriteEntry>} sprites  The sprite table.
 */
export function chairs(sprites) {
  return DESKS.map(({ chair }, i) => chairAt(sprites, i, chair))
}

/**
 * The offices' places in a page, in name order and then by id, each a box at the plate's shape, in
 * CSS pixels from the page's top left. The grid takes the number of columns that makes the offices
 * largest, the fewer rows on a tie, and is centred in the page.
 * @param {{ id: string, name: string }[]} projects
 * @param {number} width  The page's width.
 * @param {number} height  The page's height.
 * @returns {{ id: string, name: string, x: number, y: number, width: number, height: number }[]}
 */
export function tiles(projects, width, height) {
  const sorted = [...projects].sort((a, b) => compare(a.name, b.name) || compare(a.id, b.id))
  const { columns, scale } = fit(sorted.length, width, height)
  const rows = Math.ceil(sorted.length / columns)
  const w = PLATE.width * scale
  const h = PLATE.height * scale
  const left = (width - (columns * w + (columns - 1) * GAP)) / 2
  const top = (height - (rows * h + (rows - 1) * GAP)) / 2
  return sorted.map(({ id, name }, i) => ({
    id,
    name,
    x: left + (i % columns) * (w + GAP),
    y: top + Math.floor(i / columns) * (h + GAP),
    width: w,
    height: h,
  }))
}

/**
 * The one empty office a page shows when no project is active: a single office's place.
 * @param {number} width
 * @param {number} height
 */
export function lone(width, height) {
  const [only] = tiles([{ id: '', name: '' }], width, height)
  return { x: only.x, y: only.y, width: only.width, height: only.height }
}

/**
 * The offices' places in a view: every office on the overview's grid when ids is null; one office
 * zoomed in, filling the page at the plate's shape (REQ-DOCKS-004); or two side by side, each filling
 * its half of the page as when zoomed in, in the order they were picked (REQ-DOCKS-005). An id in
 * ids that isn't among the projects has no place.
 * @param {{ id: string, name: string }[]} projects
 * @param {string[] | null} ids  The offices in view, or null for the overview.
 * @param {number} width  The page's width.
 * @param {number} height  The page's height.
 * @returns {{ id: string, name: string, x: number, y: number, width: number, height: number }[]}
 */
export function framed(projects, ids, width, height) {
  if (ids === null) return tiles(projects, width, height)
  const named = new Map(projects.map((p) => [p.id, p.name]))
  const half = ids.length > 1 ? width / 2 : width
  return ids.flatMap((id, i) => {
    const name = named.get(id)
    if (name === undefined) return []
    const box = lone(half, height)
    return [{ id, name, ...box, x: box.x + i * half }]
  })
}

/**
 * The columns that make n offices largest in a page, and the scale they are drawn at.
 * @param {number} n
 * @param {number} width
 * @param {number} height
 */
export function fit(n, width, height) {
  const count = Math.max(1, n)
  let best = { columns: 1, scale: -Infinity }
  for (let columns = 1; columns <= count; columns++) {
    const rows = Math.ceil(count / columns)
    const across = (width - 2 * MARGIN - (columns - 1) * GAP) / columns / PLATE.width
    const down = (height - 2 * MARGIN - (rows - 1) * GAP) / rows / PLATE.height
    const scale = Math.min(across, down)
    // A tie goes to the fewer rows, which is the more columns, so only a larger scale wins.
    if (scale > best.scale + 1e-9 || (Math.abs(scale - best.scale) <= 1e-9 && columns > best.columns)) best = { columns, scale }
  }
  return { columns: best.columns, scale: Math.max(0, best.scale) }
}

/**
 * Compares names the same way on every machine, whatever its locale.
 * @param {string} a
 * @param {string} b
 */
function compare(a, b) {
  const x = a.toLowerCase()
  const y = b.toLowerCase()
  if (x !== y) return x < y ? -1 : 1
  return a < b ? -1 : a > b ? 1 : 0
}

/**
 * The whiteboard's face on the plate, inside its frame, measured from office.png, in plate pixels.
 * The page paints it clean and puts the sticky notes on it.
 */
export const BOARD = Object.freeze({ x: 480, y: 146, width: 151, height: 70 })

/** Room between the board's frame and its notes, in plate pixels. */
export const BOARD_PAD = 5

/** A sticky note's side at full size, in plate pixels, and the gap between notes as a share of it. */
export const NOTE = 17
export const NOTE_GAP = 0.25

/**
 * Where the sticky notes go on the board, in plan order: rows from the top left, as many to a row
 * as fit, at full size while they all fit and smaller once a phase has more than that, so they
 * always fill no more than the board's measured face.
 * @param {number} n  How many notes.
 * @param {{ x: number, y: number, width: number, height: number }} [board]
 * @returns {{ x: number, y: number, size: number }[]}  Each note's top left and side, in plate pixels.
 */
export function noteGrid(n, board = BOARD) {
  if (n <= 0) return []
  const width = board.width - 2 * BOARD_PAD
  const height = board.height - 2 * BOARD_PAD
  // The largest side at which n notes fit, trying every count of columns.
  let size = 0
  for (let columns = 1; columns <= n; columns++) {
    const rows = Math.ceil(n / columns)
    const across = width / (columns + (columns - 1) * NOTE_GAP)
    const down = height / (rows + (rows - 1) * NOTE_GAP)
    size = Math.max(size, Math.min(across, down))
  }
  size = Math.min(NOTE, size)
  const gap = size * NOTE_GAP
  // As many to a row as fit at that size.
  const columns = Math.max(1, Math.floor((width + gap + 1e-9) / (size + gap)))
  return Array.from({ length: n }, (_, i) => ({
    x: board.x + BOARD_PAD + (i % columns) * (size + gap),
    y: board.y + BOARD_PAD + Math.floor(i / columns) * (size + gap),
    size,
  }))
}

/**
 * What a whiteboard holds: the phase under way, by number, and its notes.
 * @typedef {{ n: number | null, notes: import('../vocabulary.js').Note[] }} Board
 */

/**
 * How a whiteboard changes from one state to the next: whether the phase under way changed, so its
 * notes come down and the next phase's go up, or else which notes were ticked by a story landing.
 * @param {Board | null} before  The board as it was, or null for an office not drawn before.
 * @param {Board} after
 * @returns {{ swapped: boolean, ticked: string[] }}
 */
export function boardChange(before, after) {
  if (before === null) return { swapped: false, ticked: [] }
  if (before.n !== after.n) return { swapped: true, ticked: [] }
  const was = new Set(before.notes.filter((note) => note.ticked).map((note) => note.id))
  return { swapped: false, ticked: after.notes.filter((note) => note.ticked && !was.has(note.id)).map((note) => note.id) }
}

/**
 * What an office draws at a point on its plate, found from what it drew (REQ-LABELS-002): the QA
 * lead while it checks the gates or shows a result, where it stands to do so, in front of the desks;
 * else a worker, where it sits at rest at its desk, so it is found the same while it types or walks in; else a
 * worker asking at the copier, by the session it asks for; else a worker reading at the glass
 * office, each where it stands there at rest; else the team lead on the phone, where it stands at
 * rest, at its spot or in the lounge, so it is found the same while it rocks; else a sticky note, by its place in the board's grid, so its slight tilt doesn't move it; else the
 * whiteboard's face. The leads at rest, the chairs and the room are none. Workers are tried front
 * to back.
 * @param {Record<string, SpriteEntry>} sprites  The sprite table.
 * @param {{ x: number, y: number }} point  In plate pixels.
 * @param {{ notes: string[], desks: ({ story: string, seat: Seat } | null)[], board: boolean, lead?: boolean, leadAt?: { x: number, y: number }, readers?: { story: string, seat: Seat }[], askers?: { session: string, seat: Seat }[], qa?: { at: { x: number, y: number }, result: string | null } | null }} drawn
 *   notes: the stories of the notes on the board, in plan order; desks: the worker that has each
 *   desk, from the left, and its robot; board: whether the board holds a phase; lead: whether the
 *   team lead is on the phone; leadAt: where it stands at rest, its spot unless the crew is in the
 *   lounge (client/office/retro.js); readers: the workers reading at the glass office, from the left;
 *   askers: the workers asking at the copier, from the left; qa: the QA lead while it checks or
 *   shows, where it stands, and the run whose result it shows, if it shows one. It is found by its
 *   standing pose, so its label holds still as it writes and as it shows a result.
 * @returns {{ kind: 'board' } | { kind: 'lead' } | { kind: 'note' | 'worker' | 'review', story: string } | { kind: 'prompt', session: string } | { kind: 'qa', result: string | null } | null}
 */
export function hit(sprites, point, { notes, desks, board, lead = false, leadAt = SPOTS.lead, readers = [], askers = [], qa = null }) {
  const { x, y } = point
  if (qa !== null) {
    const p = placed(sprites, 'qa', 'qa-stand', qa.at, 'body')
    if (x >= p.left && x < p.left + p.width && y >= p.head && y < p.y) return { kind: 'qa', result: qa.result }
  }
  for (let i = desks.length - 1; i >= 0; i--) {
    const worker = desks[i]
    if (worker === null || worker === undefined || DESKS[i] === undefined) continue
    const p = placed(sprites, worker.seat, `${worker.seat}-type-a`, DESKS[i].seat, 'foot')
    if (x >= p.left && x < p.left + p.width && y >= p.head && y < p.y) return { kind: 'worker', story: worker.story }
  }
  for (let i = Math.min(askers.length, COPIER.length) - 1; i >= 0; i--) {
    const asker = askers[i]
    const p = placed(sprites, asker.seat, `${asker.seat}-read`, COPIER[i], 'body')
    if (x >= p.left && x < p.left + p.width && y >= p.head && y < p.y) return { kind: 'prompt', session: asker.session }
  }
  for (let i = Math.min(readers.length, GLASS.length) - 1; i >= 0; i--) {
    const reader = readers[i]
    const p = placed(sprites, reader.seat, `${reader.seat}-read`, GLASS[i], 'body')
    if (x >= p.left && x < p.left + p.width && y >= p.head && y < p.y) return { kind: 'review', story: reader.story }
  }
  if (lead) {
    const p = placed(sprites, 'lead', 'lead-talk', leadAt, 'body')
    if (x >= p.left && x < p.left + p.width && y >= p.head && y < p.y) return { kind: 'lead' }
  }
  if (!board) return null
  if (x < BOARD.x || x >= BOARD.x + BOARD.width || y < BOARD.y || y >= BOARD.y + BOARD.height) return null
  const grid = noteGrid(notes.length)
  for (let i = 0; i < grid.length; i++) {
    const cell = grid[i]
    if (x >= cell.x && x < cell.x + cell.size && y >= cell.y && y < cell.y + cell.size) return { kind: 'note', story: notes[i] }
  }
  return { kind: 'board' }
}
